void Dispatcher_SkillInit::process_skill_init(CUser* user, ParamBase& param)
{
    // ORIG 0x081e5bdc
    if (user == 0)
    {
        return;
    }
    stSkillInit& p = static_cast<stSkillInit&>(param);
    int kind = (int)(char)p.m_8;                    // ORIG -0xc（有槽往返）
    // ORIG 0x081e5bdc：四次 `call getCurCharacSkillW` 的结果**从不落槽**——
    // `mov %eax,(%esp)` 直传 receiver（P0：原码无 slot 局部，每步现取现用）
    // ⇒ 删 slot 变量，调用点写成 receiver 内联表达式。
    ((SkillSlot*)user->getCurCharacSkillW())
        ->clear_all_skills((ENUM_SKILL_TREE_KIND)kind);
    ((SkillSlot*)user->getCurCharacSkillW())->set_parent(user);
    ((SkillSlot*)user->getCurCharacSkillW())
        ->InitSkill(false, (ENUM_SKILL_TREE_KIND)kind);
    ((SkillSlot*)user->getCurCharacSkillW())
        ->resetComboSkill((ENUM_SKILL_TREE_KIND)kind);
    user->setComboSkillSet(true);
}

Dispatcher_Antibot_DP::~Dispatcher_Antibot_DP() {}
// b28d-solo-Dispatchers verdict=DIFF(routed) [N7] ORIG 0x0820b322 orig/ours=122/116 ndiff-blocks=23
//   虚/间接调用 callee 与目标寄存器角色互换（4.4 恒目标 %eax；N7 限于 4.4.7 后端）
//   首差: push   %edi | push   %esi | sub    $0xb5c,%esp
int Dispatcher_Antibot_DP::dispatch_sig(CUser* user, PacketBuf& packet)
{
    // ORIG 0x0820b322：读嵌套包长度→checker vtbl+0x2c 解密→doDispatch 内层包。
    unsigned int binarySize = 0;
    if (!packet.get_int(binarySize))
    {
        return LineFunc(0xa795, __PRETTY_FUNCTION__, 0, 0);
    }
    char* nestedPacket = packet.get_buf_ptr(packet.get_index());
    int local_28 = 0xd;  // ORIG 局部（写后未用，保持帧形态）
    (void)local_28;
    if (binarySize > 0x567)
    {
        return LineFunc(0xa7a3, __PRETTY_FUNCTION__, 0, 0);
    }
    unsigned char outBuf[4];          // +0x00 class / +0x01..+0x03 short
    unsigned short outLen = 0xaf0;
    typedef int (*DecryptFn)(void*, int, void*, unsigned short, unsigned char*, unsigned short*);
    void* checker = GlobalData::s_antibotChecker_;
    DecryptFn fn = *reinterpret_cast<DecryptFn*>(*reinterpret_cast<void***>(checker) + (0x2c / 4));
    int ret = fn(checker, user->getAntibotKey(), nestedPacket,
                 (unsigned short)(binarySize & 0xffff), outBuf, &outLen);
    if (ret != 0)
    {
        int key = user->getAntibotKey();
        cMyTrace trace(__PRETTY_FUNCTION__, 0xa7af, 0);
        trace("[Dispatcher_Antibot_DP] Key : %d, nestedPacket : %x, binarySize : %d, return : %d",
              key, nestedPacket, binarySize, ret);
        return 0;
    }
    PacketDispatcher* dispatcher = G_PacketDispatcher();
    dispatcher->doDispatch(user,
                           (ENUM_PACKETCLASS)outBuf[0],
                           (unsigned short)*reinterpret_cast<unsigned short*>(outBuf + 1),
                           reinterpret_cast<char*>(outBuf),
                           static_cast<int>(outLen),
                           (ENUM_PACKETCLASS)1,
                           (unsigned short)0x25c);
    return 0;
}
int Dispatcher_Antibot_DP::process(CUser* user, MSG_BASE& msg, ParamBase& param) { return 0; }
int Dispatcher_Antibot_DP::read(PacketBuf& packet, MSG_BASE& msg) { return 0; }

Dispatcher_AskRematch::~Dispatcher_AskRematch() {}
// b28d-solo-Dispatchers verdict=DIFF(routed) [N7] ORIG 0x08227862 orig/ours=62/74 ndiff-blocks=11
//   虚/间接调用 callee 与目标寄存器角色互换（4.4 恒目标 %eax；N7 限于 4.4.7 后端）
//   首差: jle    08227887 <+0x25> | jne    0822788e <+0x2c> | mov    $0x1,%eax
int Dispatcher_AskRematch::dispatch_sig(CUser* user, PacketBuf& packet)
{
    bool gate;
    char rematchFlag;
    PvP_Room* room;
    int matched;

    if (user->get_state() > 2)
    {
        if (user->getCurCharacR() != 0)
            gate = false;
        else
            gate = true;
    }
    else
    {
        gate = true;
    }
    if (gate)
        return 0;
    rematchFlag = 0;
    if (!packet.get_byte(rematchFlag))
    {
        LineFunc(0xe3af,
                 __PRETTY_FUNCTION__,
                 0, 0);
        return 0;
    }
    room = (PvP_Room*)user->GetPVPRoom();
    if (room == 0)
        return 0;
    if (room->m_matching == 0)
        return 0;
    matched = room->m_matching;
    // 真实虚调用：IMatch::OnAskRematch 在镜像声明序落 +0x68（MatchRoomList.h:78），
    // 与 ORIG 0x68 槽一致（§8.5 删函数指针桥→真实虚调）。matched 局部 int 存储口径不变。
    ((IMatch*)matched)->OnAskRematch(user, (int)rematchFlag);
    return 0;
}
int Dispatcher_AskRematch::process(CUser* user, MSG_BASE& msg, ParamBase& param) { return 0; }
int Dispatcher_AskRematch::read(PacketBuf& packet, MSG_BASE& msg) { return 0; }

Dispatcher_BVHackInfo::~Dispatcher_BVHackInfo() {}
// b28d-solo-Dispatchers verdict=DIFF(routed) [N-P112] ORIG 0x08207568 orig/ours=196/190 ndiff-blocks=31
//   残余为跨版本寄存器分配/栈槽序差（P75/P112 结构性），语义已对齐
//   首差: movl   $&_ZZN21Dispatcher_BVHackInfo12dispatch_sigEP5CUserR9PacketBufE19__PRETTY_FUNCTION__,0x4(%esp) | movl   $0x0,-0xc(%ebp) | lea    -0xc(%ebp),%ea
int Dispatcher_BVHackInfo::dispatch_sig(CUser* user, PacketBuf& packet)
{
    // ORIG 0x08207568..0x08207851 (0x2e9 字节)。
    // 阈值常量 _DAT_08bd6360 = 50.0（已 objdump 核实）。

    if (user->get_state() <= 1)   // cmp $0x1 / setle
        return LineFunc(0xa216, __PRETTY_FUNCTION__, 0, 0);

    int code = 0;
    if (packet.get_int(code) != 1 || code != 0x40)
        return LineFunc(0xa21a, __PRETTY_FUNCTION__, 0, 0);

    char payload[0x40];   // -0x80
    if (packet.get_binary(payload, 0x40) != 1)
        return LineFunc(0xa21c, __PRETTY_FUNCTION__, 0, 0);

    stBVHackInfo_t info;   // -0x40（ORIG 至少 0x30 字节，6 个 double）
    if (decryptBVHackPacket(payload, info) != 1)
        return LineFunc(0xa224, __PRETTY_FUNCTION__, 0, 0);

    const double v0 = info.m_values[0];
    const double v1 = info.m_values[1];
    const double v2 = info.m_values[2];
    const double v3 = info.m_values[3];
    const double v4 = info.m_values[4];
    const double v5 = info.m_values[5];

    // 任一前五个值非零 → 记录日志（六个值按 +0x28..+0x00 顺序入 varargs）
    if (v0 != 0.0 || v1 != 0.0 || v2 != 0.0 || v3 != 0.0 || v4 != 0.0)
    {
        char* idStr = NumberToString(user->get_acc_id(), 0);
        LogManager::logFormat(
            1, "PacketDispatcher_Impl_1.cpp", __PRETTY_FUNCTION__, 0xa228,
            "(m_id: %s)(%5f)(%5f)(%5f)(%5f)(%5f)(%5f)",
            idStr, v5, v4, v3, v2, v1, v0);
    }

    if (v1 >= 50.0 && (v2 != 0.0 || v4 != 0.0))
    {
        user->getHackAnalyzer()->addServerHackCnt(
            user, (WongWork::ENUM_HACKTYPE)0x328, 1, 0, 0);
        if (user->get_state() != 5)
            user->SetTradePunishType(0x10);
    }
    return 0;
}
int Dispatcher_BVHackInfo::process(CUser* user, MSG_BASE& msg, ParamBase& param) { return 0; }
int Dispatcher_BVHackInfo::read(PacketBuf& packet, MSG_BASE& msg) { return 0; }

Dispatcher_BlueMarble::~Dispatcher_BlueMarble() {}
// b28d-solo-Dispatchers verdict=AE(routed) [P226/P0] ORIG 0x081e612c orig/ours=62/62
//   [S162] 已修：尾部具名 bool（fail = !(get_state()==0xb || ==5)）落 -0x9 并使
//   全帧槽号 +4；改条件表达式直用（ORIG 物化于 %al `test %al,%al`，P0 无槽往返）。
int Dispatcher_BlueMarble::check_error(CUser* user, MSG_BASE& msg)
{
    // ORIG 0x081e60xx 入口即 `mov 0x10(%ebp),%eax; mov %eax,-0x14(%ebp)` —— msg 引用槽
    // 在 user 判空**之前**物化（技巧13 声明位=落栈时机）；我方原放在判空之后 ⇒ 前 5 行错位。
    const MSG_BLUE_MARBLE& req = reinterpret_cast<const MSG_BLUE_MARBLE&>(msg);
    if (user == 0)
    {
        return -1;
    }
    if (req.m_0d == 6)
    {
        return 0;
    }
    if (user->getMoveSpace() != (UserSpace::T)1)
    {
        return -2;
    }
    BlueMarble* marble = static_cast<BlueMarble*>(user->getBlueMarble());
    if (marble == 0)
    {
        return -3;
    }
    // ORIG：`mov %eax,-0xc(%ebp); cmpl $-1,-0xc(%ebp); jne` —— 结果先落具名槽 -0xc、
    // 再用 mem 作 src 直分支。我方把 call 结果内联比较（技巧37 免槽形）在此点位反被
    // 4.4 折成 `cmp $-1,%eax; sete;test;je` 岛 ⇒ 此处必须建具名局部。
    const int slot = marble->getUserSlot(user);
    if (slot == -1)
    {
        return -4;
    }
    // 【batch-17 S池 P48+P84】ORIG 两臂各调一次 get_state，结果 mov$1/mov$0 物化
    // 成 bool 再 test/je 选 return（0/0xfffffffb）。具名 bool 保物化岛。
    // [b28d-solo-S162] P226/P0：ORIG 物化于 %al（`test %al,%al`）无槽往返
    // ⇒ 条件表达式直用；具名 bool 落 -0x9 并使全帧槽号 +4 漂移。
    if (!(user->get_state() == 0xb || user->get_state() == 5))
    {
        return -5;
    }
    return 0;
}
int Dispatcher_BlueMarble::process(CUser* user, MSG_BASE& msg, ParamBase& param)
{
    // ORIG 0x081e5fdc：`mov 0x14(%ebp),%eax; mov %eax,-0x14(%ebp)` —— p 先落槽，
    // 再 call check_error，结果免槽直用（`call; mov -0x14(%ebp),%edx; mov %eax,0x4(%edx)`）。
    stBlueMarble* const p = static_cast<stBlueMarble*>(&param);
    p->m_4 = check_error(user, msg);
    if (p->m_4 >= 1)
    {
        return 0;
    }
    if (p->m_4 < 0)
    {
        return LineFunc(0x60a9,
                        __PRETTY_FUNCTION__,
                        p->m_4, 0);
    }
    const MSG_BLUE_MARBLE& req = reinterpret_cast<const MSG_BLUE_MARBLE&>(msg);
    BlueMarble* marble = static_cast<BlueMarble*>(user->getBlueMarble());
    // ORIG 0x081e60xx：`cmpl $0x0,-0xc(%ebp); je <return 0 岛>` —— 非空才 fall 进
    // switch（技巧17：ORIG fall-through 块在前），空指针路径跳尾岛。
    if (marble != 0)
    {
        switch (req.m_0d)
        {
        case 0: marble->startBlueMarble(); break;
        case 1: marble->userThrowDice(user); break;
        case 2: marble->enterDungeon(user); break;
        case 3: marble->giveupDungeon(user); break;
        case 4: marble->clearDungeon(user); break;
        case 5: marble->exitDungeon(user); break;
        case 6: marble->leaveUser(user); break;
        case 7: marble->giveBonusItem(user); break;
        default: break;
        }
    }
    return 0;
}
int Dispatcher_BlueMarble::read(PacketBuf& packet, MSG_BASE& msg)
{
    MSG_BLUE_MARBLE& req = reinterpret_cast<MSG_BLUE_MARBLE&>(msg);
    if (!packet.get_byte(req.m_0d))
    {
        return LineFunc(0x609a,
                        __PRETTY_FUNCTION__,
                        0, 0);
    }
    return 0;
}
void Dispatcher_BlueMarble::send(CUser* user, ParamBase& param)
{
    // ORIG 0x081e61f4
    stBlueMarble& p = static_cast<stBlueMarble&>(param);
    if (p.m_4 == 0)
    {
        user->SendCmdOkPacket((ENUM_CMDPACKET)0x1f0);
    }
    else
    {
        user->SendCmdErrorPacket((ENUM_CMDPACKET)0x1f0,
                                 (unsigned char)(p.m_4 & 0xff));
    }
}

Dispatcher_ChangeHost::~Dispatcher_ChangeHost() {}
int Dispatcher_ChangeHost::dispatch_sig(CUser* user, PacketBuf& packet)
{
    // ORIG 0x8204c1e：state>=3 才处理；teleport_state 在 [0,3) 反走城错误 0x9e
    if (user->get_state() <= 2)
    {
        return LineFunc(0x9cbf,
                        __PRETTY_FUNCTION__,
                        0, 0);
    }
    char slot;
    if (!packet.get_byte(slot))
    {
        return LineFunc(0x9cc2,
                        __PRETTY_FUNCTION__,
                        0, 0);
    }
    // ORIG 0x8204ca4：`movl $0x0,-0x10(%ebp)` 先落 ret 的 0 初值（-0x10 远槽），
    // party 后声明占 -0xc（技巧21 声明序定槽号；ORIG 0x8204cbx `mov %eax,-0xc(%ebp)`）。
    int ret = 0;
    CParty* party = (CParty*)user->GetParty();
    if (party == 0)
    {
        user->SendCmdErrorPacket((ENUM_CMDPACKET)0x7c, 0x13);
        return 0;
    }
    if (static_cast<CPartyTelePort*>(party->GetPartyTelePort())
                ->get_teleport_state()
            >= 0
        && static_cast<CPartyTelePort*>(party->GetPartyTelePort())
                ->get_teleport_state()
            <= 3)
    {
        user->SendCmdErrorPacket((ENUM_CMDPACKET)0x7c, 0x9e);
        return 0;
    }
    ret = party->change_manager(user, (int)slot);
    if (ret > 0)
    {
        user->SendCmdErrorPacket((ENUM_CMDPACKET)0x7c, (unsigned char)ret);
    }
    return 0;
}
int Dispatcher_ChangeHost::process(CUser* user, MSG_BASE& msg, ParamBase& param) { return 0; }
int Dispatcher_ChangeHost::read(PacketBuf& packet, MSG_BASE& msg) { return 0; }

// read() 直接依赖（tsv 清单外）：G_CDataManager()+0x14 指向的基址 +0x48fc
// 为 vector<pair<int,int>>（ComboSkill.cpp 同源布局视图：6 组组合技表首列），
// 线性查 first==idx 命中返回 1，否则 0。
int Dispatcher_ComboSkill::checkComboSkillIndex(short idx)
{
    // G_CDataManager() 返回对象 +0x14 处为组合技列表基址 char*
    // （成员访问形态 mov 0x14(%eax),%eax 与 ORIG 一致；镜像视图同 ComboSkill.cpp）
    struct DataManagerComboListView
    {
        char m_pad[0x14];
        char* m_pComboList;  // +0x14
    };
    std::vector<std::pair<int, int> >* comboList =
        (std::vector<std::pair<int, int> >*)(
            ((DataManagerComboListView*)G_CDataManager())->m_pComboList + 0x48fc);
    for (int i = 0; i <= 5; ++i)
    {
        // ORIG 0x0825f2b9：循环体首 `movswl -0x1c(%ebp),%ebx`（idx 符号扩展
        // 跨 operator[] call 缓存 %ebx），比较 `cmp %eax,%ebx; sete`（技巧22/32）。
        // [b28c-30] P0 清绑：原 register int probe asm("ebx") 绑定已删（N96），
        // 改 short 形参表达式直用（P200：短整表达式作普通实参/比较直传）。
        if (idx == (*comboList)[i].first)
        {
            return 1;
        }
    }
    return 0;
}

Dispatcher_ComboSkill::~Dispatcher_ComboSkill() {}
// b28d-solo-Dispatchers verdict=DIFF(routed) [N-P112] ORIG 0x0825f3ce orig/ours=41/40 ndiff-blocks=3
//   残余为跨版本寄存器分配/栈槽序差（P75/P112 结构性），语义已对齐
//   首差: je     0825f43c <+0x6e> | jmp    0825f441 <+0x73> | mov    $0x0,%eax
int Dispatcher_ComboSkill::check_error(CUser* user, MSG_BASE& msg)
{
    const MSG_COMBO_SKILL& req = reinterpret_cast<const MSG_COMBO_SKILL&>(msg);
    // b28d-D0: P133 拆独立守卫 —— ORIG 0x0825f3e7 段三条件各自物化
    //   （user==0 直跳；state<3 出 setle；job!=9 出 setne）；合并 || 链被 4.4 折成直跳。
    if (user == 0)
    {
        return -1;
    }
    if (user->get_state() < 3)
    {
        return -1;
    }
    // b28d-D0: P226 语句表达式（无具名变量）复现 ORIG 0x0825f3f3 `setne %al;
    //   test %al,%al; je` 免槽物化（具名 bool 会 spill 到 -0x9）。
    if (({ user->get_charac_job() != 9; }))
    {
        return -1;
    }
    // b28d-solo-Dispatchers: ORIG 0x0825f41f 两条件各自 `je <mov $0,%eax>` 共享岛
    //   （负极性 && 链），正极性 || 被 4.4 折成 `jne <mov $0x13>` 反布局（P214①/P45）。
    if (req.m_pad0d != 0 && req.m_pad0d != 1)
    {
        return 0x13;
    }
    return 0;
}
// err>0 → 0；err<0 → LineFunc(0x33f)；否则当前角色 SkillSlot 写入组合技映射
// 并校验该树。
// b28d-solo-Dispatchers verdict=DIFF(routed) [N82] ORIG 0x0825f2fc orig/ours=64/62 ndiff-blocks=13
//   帧差 sub $20 vs $28 + 槽号漂移（4.1 不按 lifetime 复用栈槽）
//   首差: push   %esi | push   %ebx | sub    $0x20,%esp
int Dispatcher_ComboSkill::process(CUser* user, MSG_BASE& msg, ParamBase& param)
{
    stComboSkill& out = static_cast<stComboSkill&>(param);
    MSG_COMBO_SKILL& req = reinterpret_cast<MSG_COMBO_SKILL&>(msg);
    out.m_result = check_error(user, msg);
    if (out.m_result > 0)
    {
        return 0;
    }
    if (out.m_result < 0)
    {
        return LineFunc(0x33f,
                        __PRETTY_FUNCTION__,
                        out.m_result, 0);
    }
    SkillSlot* skillW =
        reinterpret_cast<SkillSlot*>(user->getCurCharacSkillW());
    skillW->setComboSkillInfo((ENUM_SKILL_TREE_KIND)(char)req.m_pad0d,
                              req.m_comboMap);
    skillW = reinterpret_cast<SkillSlot*>(user->getCurCharacSkillW());
    skillW->verifyComboSkillTree((ENUM_SKILL_TREE_KIND)(char)req.m_pad0d);
    return 0;
}
// 读 MSG_COMBO_SKILL：m_pad0d 树种类、树数量(≤6)、每树 {kind, 技能数(≤6),
// skillIdx...}；checkComboSkillIndex 校验通过才收技能列表；逐项插入
// m_comboMap(kind → vector<int>)。任何 get 失败按行号走 LineFunc；
// 外层 get_short 失败/循环耗尽均归 LineFunc(0x30c)。
// 【batch-17 X1 池收口（§6.2）】orig 213 / ours 210（gap 3）：调用点差集
//   25↔25 **归零**（残差 8/8 全为 pair/vector 的 C2/D2 ↔ C1/D1 同体符号名
//   对称差）；残 3 为迭代器/临时对象落槽步序（N82）⇒ 语义完成。
// b28d-solo-Dispatchers verdict=DIFF(routed) [N-P112] ORIG 0x0825ef78 orig/ours=213/210 ndiff-blocks=31
//   残余为跨版本寄存器分配/栈槽序差（P75/P112 结构性），语义已对齐
//   首差: movw   $0x0,-0x42(%ebp) | movb   $0x0,-0x43(%ebp) | movb   $0x0,-0x44(%ebp)
int Dispatcher_ComboSkill::read(PacketBuf& packet, MSG_BASE& msg)
{
    MSG_COMBO_SKILL& req = reinterpret_cast<MSG_COMBO_SKILL&>(msg);
    std::map<short, std::vector<int>, std::less<short>,
             std::allocator<std::pair<short const, std::vector<int> > > >&
        comboMap = req.m_comboMap;
    std::vector<int> skills;
    comboMap.clear();
    if (!packet.get_byte(req.m_pad0d))
    {
        return LineFunc(0x301,
                        __PRETTY_FUNCTION__,
                        0, 0);
    }
    char treeCount = 0;
    if (!packet.get_byte(treeCount))
    {
        return LineFunc(0x304,
                        __PRETTY_FUNCTION__,
                        0, 0);
    }
    for (int i = 0; i < (int)treeCount && i < 6; ++i)
    {
        short kind = 0;
        char skillCount = 0;
        if (!packet.get_short(kind))
        {
            break;  // 归 LineFunc(0x30c)
        }
        if (checkComboSkillIndex(kind))
        {
            if (!packet.get_byte(skillCount))
            {
                return LineFunc(0x312,
                                __PRETTY_FUNCTION__,
                                0, 0);
            }
            skills.clear();
            for (int j = 0; j < (int)skillCount && j < 6; ++j)
            {
                short skillIdx = 0;
                if (!packet.get_short(skillIdx))
                {
                    return LineFunc(0x319,
                                    __PRETTY_FUNCTION__,
                                    0, 0);
                }
                skills.push_back((int)skillIdx);
            }
            comboMap.insert(std::make_pair(kind, skills));
        }
    }
    return LineFunc(0x30c,
                    __PRETTY_FUNCTION__,
                    0, 0);
}
void Dispatcher_ComboSkill::send(CUser* user, ParamBase& param)
{
    stComboSkill& out = static_cast<stComboSkill&>(param);
    if (out.m_result == 0)
    {
        user->SendCmdOkPacket((ENUM_CMDPACKET)0x1fd);
    }
    else
    {
        user->SendCmdErrorPacket((ENUM_CMDPACKET)0x1fd,
                                 (unsigned char)(out.m_result & 0xff));
    }
}

Dispatcher_GM_Command::~Dispatcher_GM_Command() {}
// ---- GM 命令信号局部视图（仅本 TU 使用）----
namespace gm_pkt
{
#pragma pack(push, 1)
// SIG_FORBID_USER_TO_PLAY 前 9 字节视图（ORIG memset 9B 后按 +0/+4/+5 写）
struct SigForbidPlayBody
{
    int m_characNo;
    unsigned char m_flag;
    int m_days;
};
#pragma pack(pop)
}  // namespace gm_pkt

#include <algorithm>                          // case9 std::min（ORIG 080df90e 库调用）
// 显式路径:Game 同名空壳优先级会遮蔽 -I（CAuction.cpp 同案）
#include "../../../shared/packet/include/Packet_Monitor_Notice_Message.h"   // ORIG 真类（W ctor 0x0822bbd6，case3 GMS）
#include "../../../shared/packet/include/Packet_Forbid_Chat_By_Monitor.h"   // ORIG 真类（W ctor 0x0822bc70，case5 禁言）

// §6.2 巨件核销：P167 344/344 [0缺0多]；gap 2058→1960；残差归因 N82
// （帧/槽号全帧错位+两守卫源语句顺序）+ N78（sub $0x51c vs $0x43c 帧），语义完整
// （详见 docs/asm_translation_patterns.md 负例表）。真修：
// ① case3/5 监控包 gm_pkt::MonitorNoticeMessage/ForbidChatByMonitor 发明符号迁 ORIG
//   真类 Packet_Monitor_Notice_Message(ctor 0x0822bbd6)/Packet_Forbid_Chat_By_Monitor
//   (ctor 0x0822bc70)（显式路径 include 避 Game 同名空壳，CAuction.cpp 同案）；
// ② case4/5/6/9/0xb/0xc/0xd 补 ORIG 30B 零填充查表副本 memset+strncpy（P0 槽律）；
// ③ case9 升降级循环 if(nextLv>200) 内联化改回真实 std::min 库调用（ORIG 080df90e）；
// ④ 各 case get_int/get_str 返回值按 ORIG 不测试（bool 返回仅 get_byte 检查）；
// ⑤ 始段 accIdStr 命名缓存按 P0 内联为实参右值。
// ORIG 0x81fa19e：GM 命令分发（cmd=0..0xd）。校验链 user!=0/getCurCharacR!=0/
// get_byte 成功；失败走 LineFunc 断言路径（返回 0）。响应包 header 0x6e：
// local_1d0 = put_byte(1)+put_byte(cmd)+payload；local_1c4 = 固定拒绝包
// (put_byte(99),put_byte(1))，目标用户不存在时发给 GM 本人。
// b28d-solo-Dispatchers verdict=DIFF(routed) [N82] ORIG 0x081fa19e orig/ours=2058/1960 ndiff-blocks=355
//   帧差 sub $51c vs $42c + 槽号漂移（4.1 不按 lifetime 复用栈槽）
// [BigGM2-wave9 re-audit] 语义复核后 3 处真修（canon ndiff 1265→1221，gap 84→49，
//   calls 344/344 全平、cmp imm 0x63/0x64 差异消解）：
//   ①头部求值序：ORIG 0x81fa220-272 = get_acc_id→NumberToString→(mov %eax,%ebx)→
//     trace ctor(0x8908)——P329 ⑤ 的内联把 ctor 提前了 2 个 call，改回具名局部；
//   ②case9 result：ORIG -0x4d 为 **unsigned char** 槽（0x81fb607 `mov %al,-0x4d` 低
//     8 位截断 + 0x81fb681 `cmpb $0x0`），int→unsigned char 忠实复现截断语义；循环改
//     回 ORIG 叶块序（diff==0→升→降）+ 独立计数器形（0x81fb5b7 -0x4c/-0x48 setl/setg）；
//   ③case0xd clamp：ORIG 0x81fc20d 三分支 test/jg→cmp $0x63,jle（>99→100），三目链
//     改 if/else-if 形；④cmd 零化删（ORIG 0x81fa277 无 `movb $0` 直发 get_byte）。
//   残差 49 指令全为 4.1 码风族（源码级不可诱发，case1 已实验 `!(<=)` 反转无效）：
//   xor$1/testal（14 处，@0x81fa406）· setle+jne（14 处，@0x81fa49e）· lea 基址+add
//   拆分寻址（53 处，@0x81fa277）· ebx/esi 跨 call 寄存器缓存（@0x81fa235/0x81faaca）
//   · false-island 聚尾排布（@0x81fc41a..）。struct=549 与上述族一一对应。判 N82+N78 维持。
//   首差: sub    $0x51c,%esp | movl   $&_ZZN21Dispatcher_GM_Command12dispatch_sigEP5CUserR9PacketBufE19__PRETTY_FUNCTION__,0x4(%esp) | movl   $&_ZZN21Dispatcher
// [SweepDispatchers 2026-09-09] 独立复核：p167 344/344 仅剩 C1/C2/D1/D2 同址别名（P93）；
//   多重集差 133/63 全为上述 4.1 码风族（add 链 53 / setle 14 / xor 14 / mov$imm 30）；
//   无缺失 callee/分支 ⇒ 维持 N82+N78（wave9 三处真修仍在；当前 1975 vs ORIG 2058）。
// [SweepDispatchers3 2026-09-09] 本轮四处修复：①14 处守卫改负向早退 break（复现 ORIG
//   xor$1/test/jne 14 处 + setle/test/jne 14 处；探针 /tmp/probe_gm2.cpp f10 逐条同形）；
//   ②cmd/len/extra/name/text 改 GmCmdArgs pack(1) 视图（成员取址 = ORIG lea 基址+add 偏移
//   53 处；探针 /tmp/probe_view.cpp）；③case4 查找键改回 ORIG 的 name(+0x12)——lookupName
//   的 memset/strncpy 是原码死写入（P171）；④删 len/wLen/extra/target 零初始化。
//   gap 83→20（2005 vs ORIG 2025），残差 = cMyTrace varargs 寄存器缓存（N80/N7 族）。
namespace
{
// ORIG dispatch_sig 的参数缓冲视图（偏移照 ORIG 反汇编 @0x81fa277..）：
// cmd@+0x0d / len@+0x0e，其余成员按 case 复用 +0x12 起区域（union 视角）。
// 取址经「lea 基址; add 偏移」正是 ORIG 4.1 形态（探针 /tmp/probe_view.cpp 实证
// 4.4.7 对局部结构体成员取址同形）。
#pragma pack(push,1)
struct GmCmdArgs
{
    char m_pad0[0xd];
    unsigned char cmd;      // +0x0d
    int len;                // +0x0e
    union
    {
        char text[0x100];                                          // +0x12（case1/2/3 公告）
        struct { char name[0x1e]; } kick;                          // +0x12（case4/0xb/0xc）
        struct { int extra; char name[0x1e]; } chat;               // +0x12/+0x16（case5/6/9/0xd）
        struct { unsigned short wLen; int extra; char name[0x1e]; } item;  // +0x12/+0x14/+0x18（case10）
    } u;
};
#pragma pack(pop)
}
int Dispatcher_GM_Command::dispatch_sig(CUser* user, PacketBuf& packet)
{
    if (user == 0)
    {
        // ORIG 0x81fa1e4：LineFunc(0x88fd, pretty, 0, 0) 断言后返回其值。
        return LineFunc(0x88fd, __PRETTY_FUNCTION__, 0, 0);
    }
    if (user->getCurCharacR() == 0)
    {
        // ORIG 0x81fa224：LineFunc(0x8902, pretty, 0, 0) 断言后返回其值。
        return LineFunc(0x8902, __PRETTY_FUNCTION__, 0, 0);
    }

    {
        // ORIG 0x81fa235：NumberToString 先求值并缓存（mov %eax,%ebx），随后才发
        // cMyTrace(0x8908) ctor——内联回实参位会把 ctor 提前到两个 call 之前（实测
        // 头部 +6/-6 错位）。按 ORIG 求值序固定为具名局部。
        const char* accIdStr = NumberToString(user->get_acc_id(), 0);
        cMyTrace trace(__PRETTY_FUNCTION__, 0x8908, 0);
        trace("GM Command : %s", accIdStr);
    }

    // ORIG 0x81fa277：cmd 无初始化直发 get_byte（失败路径 LineFunc 返回，不经读
    // cmd；成功路径必写），删多余的 movb $0 零化。cmd/len/extra/name/text 全部
    // 走 GmCmdArgs 视图，取址形态 = ORIG 的 lea 基址+add 偏移。
    GmCmdArgs args;
    if (!packet.get_byte(args.cmd))
    {
        // ORIG 0x81fa2cb：LineFunc(0x890e, pretty, 0, 0) 断言后返回其值。
        return LineFunc(0x890e, __PRETTY_FUNCTION__, 0, 0);
    }

    PacketGuard reject;   // ORIG local_1c4：目标缺失时的固定应答
    reject.put_header(1, 0x6e);
    reject.put_byte(1);
    reject.put_byte(99);
    reject.put_byte(1);
    reject.finalize(true);

    PacketGuard resp;     // ORIG local_1d0
    resp.put_header(1, 0x6e);
    resp.put_byte(1);
    resp.put_byte(args.cmd);

    // ORIG 读包文本布局见 GmCmdArgs 注释；查表副本仍是独立栈缓冲。
    char targetName[0x1e];   // case9 ORIG local_248：调级目标的零填充副本
    char lookupName[0x1e];   // ORIG case4/5/6/0xb/0xc/0xd 各自的 30B 零填充查表副本
    //（P0 槽律：ORIG 每分支 memset(+strncpy) 槽往返实证，非内联右值）
    CUser* target;
    switch (args.cmd)
    {
    case 0:  // 切换 GM 模式（无参数）
        if (GlobalData::s_GM_Manager->GetGmLevel(user->get_acc_id()) <= GM_LV0)
            break;
        {
            // ORIG 0x81fa420：if/else 两次字面 SetGameMasterMode（mode==1→false，否则 true）
            if (GlobalData::s_GM_Manager->GetCurrentGmMode(user->get_acc_id()) != 1)
                user->SetGameMasterMode(true);
            else
                user->SetGameMasterMode(false);
            GlobalData::s_GM_Manager->TurnGmMode(user->get_acc_id());
        }
        break;
    case 1:  // 全服公告 GMC <str>
        // ORIG 守卫链：GmMode==1 与 GetGmLevel>0 各自 test/jne；get_int/get_str 返回值
        // 不测试（0x81fa4eb 只读 len 槽判 0）。
        if (GlobalData::s_GM_Manager->GetCurrentGmMode(user->get_acc_id()) != 1)
            break;
        if (GlobalData::s_GM_Manager->GetGmLevel(user->get_acc_id()) <= GM_LV0)
            break;
        {
            packet.get_int(args.len);
            packet.get_str(args.u.text, 0x100, args.len);
            if (args.len != 0)
            {
            resp.put_int(args.len);
            resp.put_str(args.u.text, args.len);
            resp.finalize(true);
            G_GameWorld()->send_all(resp);
            // ORIG 0x8939：全服广播后记日志
            cMyTrace trace(__PRETTY_FUNCTION__, 0x8939, 0);
            trace("GMC %s \n", args.u.text);
            }
        }
        break;
    case 2:  // 本区域公告 GMZ <str>
        if (GlobalData::s_GM_Manager->GetCurrentGmMode(user->get_acc_id()) != 1)
            break;
        if (GlobalData::s_GM_Manager->GetGmLevel(user->get_acc_id()) <= GM_LV0)
            break;
        {
            packet.get_int(args.len);
            packet.get_str(args.u.text, 0x100, args.len);
            if (args.len != 0)
            {
            resp.put_int(args.len);
            resp.put_str(args.u.text, args.len);
            resp.finalize(true);
            G_GameWorld()->send_to_area(
                user->getCurCharacVill(), user->get_area(false), resp);
            // ORIG 0x894a：区域广播后记日志
            cMyTrace trace(__PRETTY_FUNCTION__, 0x894a, 0);
            trace("GMZ %s \n", args.u.text);
            }
        }
        break;
    case 3:  // 监控服公告 GMS <str>（resp 仅 finalize 不发送，ORIG 同）
        if (GlobalData::s_GM_Manager->GetCurrentGmMode(user->get_acc_id()) != 1)
            break;
        if (GlobalData::s_GM_Manager->GetGmLevel(user->get_acc_id()) <= GM_LV0)
            break;
        {
            packet.get_int(args.len);
            packet.get_str(args.u.text, 0x100, args.len);
            if (args.len != 0)
            {
            resp.put_int(args.len);
            resp.put_str(args.u.text, args.len);
            resp.finalize(true);
            Packet_Monitor_Notice_Message noti;   // ORIG ctor 0x0822bbd6：PacketHeader(0x9dc,0x10b)+memset(m_text)
            noti.m_len = (unsigned char)args.len;
            strncpy(noti.m_text, args.u.text, args.len);   // ORIG strncpy 到 +0xb（m_text）
            CMonitorServerProxy* proxy = GlobalData::s_monitor_proxy_mgr->GetServerProxy(
                user->GetServerGroup());
            proxy->SendTcpPacket((char*)&noti, 0x10b);
            // ORIG 0x8966：监控公告发送后记日志
            cMyTrace trace(__PRETTY_FUNCTION__, 0x8966, 0);
            trace("GMS %s \n", args.u.text);
            }
        }
        break;
    case 4:  // 踢人 expel <name>
        if (GlobalData::s_GM_Manager->GetCurrentGmMode(user->get_acc_id()) != 1)
            break;
        if (GlobalData::s_GM_Manager->GetGmLevel(user->get_acc_id()) <= GM_LV0)
            break;
        {
            packet.get_int(args.len);
            packet.get_str(args.u.kick.name, 0x1e, args.len);
            memset(lookupName, 0, sizeof(lookupName));
            strncpy(lookupName, args.u.kick.name, (size_t)args.len);
            // ORIG 0x81fa9c9：查找键是 get_str 目标本身（+0x12），lookupName 的
            // memset/strncpy 是原码死写入（P171 照抄）。
            target = G_GameWorld()->find_user_from_world_byaccid(
                G_GameWorld()->GetIDUserInIDMap(args.u.kick.name));
            if (target == 0)
            {
                user->Send(reject);
            }
            else
            {
                resp.put_int(args.len);
                resp.put_str(args.u.kick.name, args.len);
                resp.finalize(true);
                user->Send(resp);
                target->Send(resp);
                target->DisConnSig((DISCONN_SIG)0x14, true, 0);
            }
            // ORIG 0x8993：踢人日志（目标在/不在都记）
            cMyTrace trace(__PRETTY_FUNCTION__, 0x8993, 0);
            trace("GM(%s) expel %s \n", user->getCurCharacName(), args.u.kick.name);
        }
        break;
    case 5:  // 禁言 forbid chat <mins> <nameLen> <name>
        if (GlobalData::s_GM_Manager->GetCurrentGmMode(user->get_acc_id()) != 1)
            break;
        if (GlobalData::s_GM_Manager->GetGmLevel(user->get_acc_id()) <= GM_LV0)
            break;
        {
            packet.get_int(args.len);
            packet.get_int(args.u.chat.extra);
            packet.get_str(args.u.chat.name, 0x1e, args.u.chat.extra);
            // ORIG local_7c：分钟→秒钳制（<1→60s；>=0x5a0→0x15180=1 天）
            int sec = (args.len < 0x5a0) ? ((args.len < 1) ? 0x3c : args.len * 0x3c) : 0x15180;
            memset(lookupName, 0, sizeof(lookupName));
            strncpy(lookupName, args.u.chat.name, (size_t)args.u.chat.extra);
            target = G_GameWorld()->find_user_from_world_byaccid(
                G_GameWorld()->GetIDUserInIDMap(lookupName));
            if (target == 0)
            {
                user->Send(reject);
            }
            else
            {
                G_GameWorld()->DisableChat(args.u.chat.name, sec);
                // ORIG 0x89b8：定时器入队日志（%d=目标 characNo）
                {
                    cMyTrace trace(__PRETTY_FUNCTION__, 0x89b8, 0);
                    trace("Insert timer queue @ forbidchat: %s %d\n",
                          args.u.chat.name, target->getCurCharacNo());
                }
                G_TimerQueue()->InsertTimer(TimerEntry::OBJ_TYPE_0,
                                            (int)target->GetUID(),
                                            (TIMER_MESSAGE)0x5d, sec,
                                            (int)target->GetLoginTick(),
                                            (unsigned int)target->getCurCharacNo());
                resp.put_int(args.len);
                resp.put_int(args.u.chat.extra);
                resp.put_str(args.u.chat.name, args.u.chat.extra);
                resp.finalize(true);
                user->Send(resp);
                target->Send(resp);
                // ORIG Packet_Forbid_Chat_By_Monitor：ctor 0x0822bc70（PacketHeader(0x9dd,0x30)
                // + memset(m_name)），m_secs=秒、m_name=名（m_padE 无写入，头注释同证）
                Packet_Forbid_Chat_By_Monitor moni;
                moni.m_secs = sec;
                strncpy(moni.m_name, args.u.chat.name, (size_t)args.u.chat.extra);
                CMonitorServerProxy* proxy =
                    GlobalData::s_monitor_proxy_mgr->GetServerProxy(
                        target->GetServerGroup());
                proxy->SendTcpPacket((char*)&moni, 0x30);
                // ORIG 0x89ce：操作日志（%d=分钟数）
                cMyTrace trace(__PRETTY_FUNCTION__, 0x89ce, 0);
                trace("GM(%s) forbid chat %s for %d mins \n",
                      user->getCurCharacName(), args.u.chat.name, args.len);
            }
        }
        break;
    case 6:  // 禁移动 forbid move <mins> <nameLen> <name>（仅 state==3 生效）
        if (GlobalData::s_GM_Manager->GetCurrentGmMode(user->get_acc_id()) != 1)
            break;
        if (GlobalData::s_GM_Manager->GetGmLevel(user->get_acc_id()) <= GM_LV0)
            break;
        {
            packet.get_int(args.len);
            packet.get_int(args.u.chat.extra);
            packet.get_str(args.u.chat.name, 0x1e, args.u.chat.extra);
            int sec = (args.len < 0x5a0) ? ((args.len < 1) ? 0x3c : args.len * 0x3c) : 0x15180;
            memset(lookupName, 0, sizeof(lookupName));
            strncpy(lookupName, args.u.chat.name, (size_t)args.u.chat.extra);
            target = G_GameWorld()->find_user_from_world_byaccid(
                G_GameWorld()->GetIDUserInIDMap(lookupName));
            if (target == 0)
            {
                user->Send(reject);
            }
            else if (target->get_state() == 3)
            {
                G_GameWorld()->DisableMove(args.u.chat.name, sec);
                // ORIG 0x89fe：定时器入队日志
                {
                    cMyTrace trace(__PRETTY_FUNCTION__, 0x89fe, 0);
                    trace("Insert timer queue @ forbidmove: %s %d\n",
                          args.u.chat.name, target->getCurCharacNo());
                }
                G_TimerQueue()->InsertTimer(TimerEntry::OBJ_TYPE_0,
                                            (int)target->GetUID(),
                                            (TIMER_MESSAGE)0x5e, sec,
                                            (int)target->GetLoginTick(),
                                            (unsigned int)target->getCurCharacNo());
                resp.put_int(args.len);
                resp.put_int(args.u.chat.extra);
                resp.put_str(args.u.chat.name, args.u.chat.extra);
                resp.finalize(true);
                user->Send(resp);
                target->Send(resp);
                // ORIG 0x8a09：操作日志
                cMyTrace trace(__PRETTY_FUNCTION__, 0x8a09, 0);
                trace("GM(%s) forbid move %s for %d mins \n",
                      user->getCurCharacName(), args.u.chat.name, args.len);
            }
            // state!=3：ORIG 无任何回包/动作
        }
        break;
    case 7:  // 隐身
        if (GlobalData::s_GM_Manager->GetCurrentGmMode(user->get_acc_id()) != 1)
            break;
        if (GlobalData::s_GM_Manager->GetGmLevel(user->get_acc_id()) <= GM_LV0)
            break;
        {
            user->SetInvisible();
            if (user->get_state() == 3)
            {
                user->SendNotiPacket((CUser::eSendTarget)0, (ENUM_NOTIPACKET)2, 0);
            }
            // ORIG 0x8a2b
            cMyTrace trace(__PRETTY_FUNCTION__, 0x8a2b, 0);
            trace("GM(%s) is invisible \n", user->getCurCharacName());
        }
        break;
    case 8:  // 现身
        if (GlobalData::s_GM_Manager->GetCurrentGmMode(user->get_acc_id()) != 1)
            break;
        if (GlobalData::s_GM_Manager->GetGmLevel(user->get_acc_id()) <= GM_LV0)
            break;
        {
            user->SetVisible();
            if (user->get_state() == 3)
            {
                user->SendNotiPacket((CUser::eSendTarget)0, (ENUM_NOTIPACKET)2, 0);
            }
            // ORIG 0x8a43
            cMyTrace trace(__PRETTY_FUNCTION__, 0x8a43, 0);
            trace("GM(%s) is visible \n", user->getCurCharacName());
        }
        break;
    case 9:  // 调级 setlevel <level> <nameLen> <name>
        if (GlobalData::s_GM_Manager->GetCurrentGmMode(user->get_acc_id()) != 1)
            break;
        if (GlobalData::s_GM_Manager->GetGmLevel(user->get_acc_id()) <= GM_LV0)
            break;
        {
            packet.get_int(args.len);
            packet.get_int(args.u.chat.extra);
            packet.get_str(args.u.chat.name, 0x1e, args.u.chat.extra);
            // ORIG local_248：调级目标用零填充副本查表；回包/日志仍用读入文本 name。
            // （原实现误 memset(name) 致目标永远查不到。）
            memset(targetName, 0, sizeof(targetName));
            strncpy(targetName, args.u.chat.name, (size_t)args.u.chat.extra);
            target = G_GameWorld()->find_user_from_world_byaccid(
                G_GameWorld()->GetIDUserInIDMap(targetName));
            if (target == 0)
            {
                user->Send(reject);
            }
            else
            {
                int diff = args.len - target->get_charac_level();
                // ORIG -0x4d 为 **unsigned char** 槽（mov %al,-0x4d 低 8 位截断 +
                // cmpb $0x0 判 0）：最后一次 SetCharacLevel 的返回（!=0 才回包；
                // diff==0 静默）。叶块序 = ORIG 物理序：diff==0 → 升（>0）→ 降（<0）。
                unsigned char result = 0;
                if (diff == 0)
                {
                    result = 0;
                }
                else if (diff > 0)
                {
                    for (int i = 0; i < diff; ++i)
                    {
                        int nextLv = target->get_charac_level() + 1;
                        int lvCap = 200;
                        result = target->SetCharacLevel(
                            std::min(lvCap, nextLv));
                    }
                }
                else
                {
                    for (int i = 0; i > diff; --i)
                    {
                        int nextLv = target->get_charac_level() - 1;
                    int lvCap = 200;
                    result = target->SetCharacLevel(
                        std::min(lvCap, nextLv));
                    }
                }
                if (result != 0)
                {
                    int st = target->get_state();
                    if (st == 3)
                    {
                        target->SendNotiPacket((CUser::eSendTarget)1, (ENUM_NOTIPACKET)0x25, 0);
                        target->SendNotiPacket((CUser::eSendTarget)0, (ENUM_NOTIPACKET)2, 0);
                        target->SendNotiPacket((CUser::eSendTarget)1, (ENUM_NOTIPACKET)2, 1);
                    }
                    else if (st == 5)
                    {
                        target->SendNotiPacket((CUser::eSendTarget)1, (ENUM_NOTIPACKET)0x25, 0);
                        target->SendNotiPacket((CUser::eSendTarget)2, (ENUM_NOTIPACKET)2, 1);
                    }
                    resp.put_int(args.len);
                    resp.put_int(args.u.chat.extra);
                    resp.put_str(args.u.chat.name, args.u.chat.extra);
                    resp.finalize(true);
                    user->Send(resp);
                    target->Send(resp);
                    // ORIG 0x8a89
                    cMyTrace trace(__PRETTY_FUNCTION__, 0x8a89, 0);
                    trace("GM(%s) modify %s level to %d \n",
                          user->getCurCharacName(), args.u.chat.name, args.len);
                }
            }
        }
        break;
    case 10:  // 发物品 grant item <itemIdx> <count> <nameLen> <name>
        if (GlobalData::s_GM_Manager->GetCurrentGmMode(user->get_acc_id()) != 1)
            break;
        if (GlobalData::s_GM_Manager->GetGmLevel(user->get_acc_id()) <= GM_LV0)
            break;
        {
            packet.get_int(args.len);
            packet.get_short(args.u.item.wLen);
            packet.get_int(args.u.item.extra);
            packet.get_str(args.u.item.name, 0x1e, args.u.item.extra);
            memset(lookupName, 0, sizeof(lookupName));
            strncpy(lookupName, args.u.item.name, (size_t)args.u.item.extra);
            target = G_GameWorld()->find_user_from_world_byaccid(
                G_GameWorld()->GetIDUserInIDMap(lookupName));
            if (target == 0)
            {
                user->Send(reject);
            }
            else
            {
                ENUM_ITEMSPACE space = (ENUM_ITEMSPACE)0;
                int slot = target->AddItem(args.len, (int)(unsigned short)args.u.item.wLen,
                                           (eItemAddReason)6, space, 0);
                if (slot >= 0)
                {
                    // ORIG 0x8ab0：成功发物品日志（先于 SendUpdateItemList）
                    {
                        cMyTrace trace(__PRETTY_FUNCTION__, 0x8ab0, 0);
                        trace("GM(%s) granted Item(%d) to %s.",
                              user->getCurCharacName(), slot,
                              target->getCurCharacName());
                    }
                    target->SendUpdateItemList((CUser::eSendTarget)1, space, slot);
                    resp.put_int(args.len);
                    resp.put_short(args.u.item.wLen);
                    resp.put_int(args.u.item.extra);
                    resp.put_str(args.u.item.name, args.u.item.extra);
                    resp.finalize(true);
                    user->Send(resp);
                    // ORIG 0x8aba
                    cMyTrace trace(__PRETTY_FUNCTION__, 0x8aba, 0);
                    trace("GM(%s) grant item(%d) to %s \n",
                          user->getCurCharacName(), args.len, args.u.item.name);
                }
            }
        }
        break;
    case 0xb:  // 复活 revive <name>
        if (GlobalData::s_GM_Manager->GetCurrentGmMode(user->get_acc_id()) != 1)
            break;
        if (GlobalData::s_GM_Manager->GetGmLevel(user->get_acc_id()) <= GM_LV0)
            break;
        {
            packet.get_int(args.len);
            packet.get_str(args.u.kick.name, 0x1e, args.len);
            memset(lookupName, 0, sizeof(lookupName));
            strncpy(lookupName, args.u.kick.name, (size_t)args.len);
            target = G_GameWorld()->find_user_from_world_byaccid(
                G_GameWorld()->GetIDUserInIDMap(lookupName));
            if (target == 0)
            {
                user->Send(reject);
            }
            else
            {
                // ORIG 0x2680：target 有 party 才干活；无 party 独立再发 reject
                CParty* party = (CParty*)target->GetParty();
                if (party == 0)
                {
                    user->Send(reject);
                }
                else
                {
                    party->set_charac_live(target, (ENUM_USER_DUNGEON_STATE)1);
                    resp.put_int(args.len);
                    resp.put_str(args.u.kick.name, args.len);
                    resp.finalize(true);
                    user->Send(resp);
                    target->Send(resp);
                    // ORIG 0x8ae2
                    cMyTrace trace(__PRETTY_FUNCTION__, 0x8ae2, 0);
                    trace("GM(%s) revive %s \n", user->getCurCharacName(), args.u.kick.name);
                }
            }
        }
        break;
    case 0xc:  // 重置疲劳 reset fatigue <name>
        if (GlobalData::s_GM_Manager->GetCurrentGmMode(user->get_acc_id()) != 1)
            break;
        if (GlobalData::s_GM_Manager->GetGmLevel(user->get_acc_id()) <= GM_LV0)
            break;
        {
            packet.get_int(args.len);
            packet.get_str(args.u.kick.name, 0x1e, args.len);
            memset(lookupName, 0, sizeof(lookupName));
            strncpy(lookupName, args.u.kick.name, (size_t)args.len);
            target = G_GameWorld()->find_user_from_world_byaccid(
                G_GameWorld()->GetIDUserInIDMap(lookupName));
            if (target == 0)
            {
                user->Send(reject);
            }
            else
            {
                target->RecoverFatigue(0);
                target->SendFatigue();
                resp.put_int(args.len);
                resp.put_str(args.u.kick.name, args.len);
                resp.finalize(true);
                user->Send(resp);
                target->Send(resp);
                // ORIG 0x8b09
                cMyTrace trace(__PRETTY_FUNCTION__, 0x8b09, 0);
                trace("GM(%s) reset fatigue %s \n", user->getCurCharacName(), args.u.kick.name);
            }
        }
        break;
    case 0xd:  // 封号 forbid play <days> <nameLen> <name>（发 SIG_FORBID_USER_TO_PLAY 到 DB 队列）
        if (GlobalData::s_GM_Manager->GetCurrentGmMode(user->get_acc_id()) != 1)
            break;
        if (GlobalData::s_GM_Manager->GetGmLevel(user->get_acc_id()) <= GM_LV0)
            break;
        {
            packet.get_int(args.len);
            packet.get_int(args.u.chat.extra);
            packet.get_str(args.u.chat.name, 0x1e, args.u.chat.extra);
            memset(lookupName, 0, sizeof(lookupName));
            strncpy(lookupName, args.u.chat.name, (size_t)args.u.chat.extra);
            target = G_GameWorld()->find_user_from_world_byaccid(
                G_GameWorld()->GetIDUserInIDMap(lookupName));
            if (target == 0)
            {
                user->Send(reject);
            }
            else
            {
                Stream* stream = GlobalData::s_stream_pool->Acquire(
                    "PacketDispatcher_Impl_1.cpp", 0x8b28);
                CStreamGuard guard(stream, true);
                // ORIG：*guard → operator*（0x80c8c46），GetInBuffer 走 operator->（0x80c8c4e）。
                **guard << 0x93;
                **guard << (int)user->GetUID();
                SIG_FORBID_USER_TO_PLAY* sig =
                    guard->GetInBuffer<SIG_FORBID_USER_TO_PLAY>();
                memset(sig, 0, 9);
                gm_pkt::SigForbidPlayBody* body =
                    (gm_pkt::SigForbidPlayBody*)sig;
                body->m_characNo = target->getCurCharacNo();
                body->m_flag = 1;
                // ORIG 0x81fc20d：三分支落码 test/jg → cmp $0x63,jle（[1,100] 钳制），
                // 叶块序 = (<=0)→1 → (>99)→100 → 原值。
                if (args.len <= 0)
                    body->m_days = 1;
                else if (args.len > 99)
                    body->m_days = 100;
                else
                    body->m_days = args.len;
                GlobalData::s_msgq_mgr->put((MsgQueueMgr::QUEUE_IDX)2, guard);
                resp.put_int(args.len);
                resp.put_int(args.u.chat.extra);
                resp.put_str(args.u.chat.name, args.u.chat.extra);
                resp.finalize(true);
                user->Send(resp);
                target->Send(resp);
                // ORIG 0x8b44
                cMyTrace trace(__PRETTY_FUNCTION__, 0x8b44, 0);
                trace("GM(%s) forbid play %s for %d days \n",
                      user->getCurCharacName(), args.u.chat.name, args.len);
            }
        }
        break;
    default:
        // ORIG 0x8b52：未知 GM 命令日志（%d=cmd，%s=accId）
        cMyTrace trace(__PRETTY_FUNCTION__, 0x8b52, 0);
        trace("Undifined GM Command : %d by %s", (int)args.cmd,
              NumberToString(user->get_acc_id(), 0));
        break;
    }
    return 0;
}
