Dispatcher_SecurityLog::~Dispatcher_SecurityLog() {}
// b28d-solo-Dispatchers verdict=DIFF(routed) [N-P112] ORIG 0x0825fb38 orig/ours=76/77 ndiff-blocks=12
//   残余为跨版本寄存器分配/栈槽序差（P75/P112 结构性），语义已对齐
//   首差: mov    0x14(%ebp),%eax | mov    %eax,-0x24(%ebp) | mov    0x10(%ebp),%eax
int Dispatcher_SecurityLog::process(CUser* user, MSG_BASE& msg, ParamBase& param)
{
    // ORIG 0x0825fb38：acc_id = user==0 ? 0 : user->get_acc_id()；
    // 当 *(int*)(msg+0x15)!=0 且 *(int*)(msg+0x19)!=0 时
    // LogManager::logFormat(1, "PacketDispatcher_Impl_2.cpp", PRETTY, 0x9d0,
    //   "Delay check, mode:%d, value:%d, %d, %d, %d, %d, %d, m_id:%s",
    //   *(msg+0xd), *(msg+0x11), *(msg+0x15), *(msg+0x19), *(msg+0x1d), *(msg+0x21),
    //   *(int*)(msg+0x1d) - *(int*)(msg+0x19), NumberToString(acc_id, 0))；
    // 恒返 0。
    unsigned int accId;
    if (user == 0)
    {
        accId = 0;
    }
    else
    {
        accId = user->get_acc_id();
    }
    const MSG_SECURITY_LOG_PACKET* m =
        reinterpret_cast<const MSG_SECURITY_LOG_PACKET*>(&msg);
    if (m->m_logCounts[1] != 0 && m->m_logCounts[2] != 0)  // msg+0x15 / +0x19
    {
        LogManager::logFormat(
            1, "PacketDispatcher_Impl_2.cpp",
            __PRETTY_FUNCTION__,
            0x9d0,
            "Delay check, mode:%d, value:%d, %d, %d, %d, %d, %d, m_id:%s",
            m->m_field0d,                                   // msg+0xd
            (int)m->m_logCounts[0],                         // msg+0x11
            (int)m->m_logCounts[1],                         // msg+0x15
            (int)m->m_logCounts[2],                         // msg+0x19
            (int)m->m_logCounts[3],                         // msg+0x1d
            (int)m->m_logCounts[4],                         // msg+0x21
            (int)m->m_logCounts[3] - (int)m->m_logCounts[2],
            NumberToString(accId, 0));
    }
    return 0;
}
// b28d-solo-Dispatchers verdict=NEAR(routed) [S206 收敛 DIFF→NEAR] ORIG 0x0825fabc
//   [P0/P211/P205] 已修：删 msg 指针局部（形参槽直用）、first 去预清零、+0xd 改具名
//   视图（disp 直存）、循环地址改 `msg+(i+4)*4+1` 加法序；残余仅寄存器/槽名差
//   （P75/P112 结构性，助记符序列已全等）。
int Dispatcher_SecurityLog::read(PacketBuf& packet, MSG_BASE& msg)
{
    // ORIG 0x0825fabc：int 中转 → 0xd；循环 5 个 int → 0x11/0x15/0x19/0x1d/0x21；失败 0x99a/0x9a2
    // [b28d-solo-S206] P0：ORIG 0x0825fabc 无 msg 指针局部（`lea -0x10(%ebp),%eax`
    //   直传 &first，`mov 0x10(%ebp),%eax` 直接用形参槽）+ first 无预清零
    //   （无 movl $0）⇒ 删指针局部、去初始化式。
    int first;
    if (!packet.get_int(first))
        return 0x99a;
    // [b28d-solo-S206] P211 档③ + disp 折叠：ORIG `mov 0x10(%ebp),%eax;
    //   mov -0x10(%ebp),%edx; mov %edx,0xd(%eax)`（LHS msg 先载、值直存 disp）；
    //   裸 cast 解引用恒产 lea+中转 ⇒ 改具名视图成员。
    struct __attribute__((packed)) SecurityLogView
    {
        char m_head[0xd];
        int m_first;              // +0x0d
    };
    reinterpret_cast<SecurityLogView*>((char*)&msg)->m_first = first;
    for (int i = 0; i < 5; ++i)
    {
        // [b28d-solo-S206] P205/P30：ORIG 加法序 `…shl $2; add %edx,%eax; add $1,%eax`
        //   （+1 加在基址之后）⇒ 指针形 `msg + (i+4)*4 + 1`（左结合）已使 4.4 把
        //   +1 折进索引侧、仅差 1 条 add 位置；整型加法形（探针 probe_add2 g/h）
        //   实测更劣（+3 条 lea/mov 且寄存器角色反）⇒ 保留指针形，残差记 N（P205）。
        if (!packet.get_int(*reinterpret_cast<unsigned int*>(
                (char*)&msg + (i + 4) * 4 + 1)))
            return 0x9a2;
    }
    return 0;
}
void Dispatcher_SecurityLog::send(CUser* user, ParamBase& param) {}

