// b28d-solo-Dispatchers verdict=DIFF(routed) [N-P112] ORIG 0x081ff7de orig/ours=165/160 ndiff-blocks=10
//   残余为跨版本寄存器分配/栈槽序差（P75/P112 结构性），语义已对齐
//   首差: movswl %ax,%ebx | sete   %al | test   %al,%al
int Dispatcher_Select_Card::dispatch_sig(CUser* user, PacketBuf& packet)
{
    // ORIG 0x081ff7de: state==5 门
    if (user->get_state() != 5)
        return 0;

    // +0x02c: getMoveSpace()==1 → 放弃
    if (user->getMoveSpace() == 1)
        return 0;

    // +0x04b: GetPartyIndex → CGameManager::GetParty
    // ORIG 0x81ff829：GetPartyIndex 返回 movswl %ax,%ebx 单条 sext 入 %ebx（asm 具名，无槽）
    // [b28d-solo-S206] P200：ORIG `call GetPartyIndex; movswl %ax,%ebx`（无栈槽）⇒
    //   删具名 partyIndex，内联实参直传。
    CParty* party = G_CGameManager()->GetParty(user->GetPartyIndex());
    if (party == 0)
    {
        return LineFunc(0x9371, __PRETTY_FUNCTION__, 0, 0);
    }

    // +0x0a8: 副本为 TowerOfDespair → 放弃
    if (party->m_battleField.m_pDungeon != 0 && party->m_battleField.m_pDungeon->isTowerOfDespairDungeon())
        return 0;

    // +0x0e4: 读 cardType（0..1 有效）
    char cardType;                 // ORIG 槽 -0xe 无初始化
    if (!packet.get_byte(cardType))
    {
        return LineFunc(0x9382, __PRETTY_FUNCTION__, 0, 0);
    }
    if (cardType < 0 || cardType > 1)
    {
        return LineFunc(0x9384, __PRETTY_FUNCTION__, 0, 0);
    }

    // +0x15f: 读 cardNo
    char cardNo;                   // ORIG 槽 -0xd 无初始化
    if (!packet.get_byte(cardNo))
    {
        return LineFunc(0x9392, __PRETTY_FUNCTION__, 0, 0);
    }

    // +0x19a: clear_state > 4 → 放弃
    if (party->get_dungeon_clear_state() > 4)
        return 0;

    // +0x1c0: 全员未选卡完成才登记
    if (!party->IsCompleteCardSelectOfMembers(static_cast<eClearRewardCardType_t>(2)))
    {
        // +0x1ef: SetCardNumber(user, cardNo, cardType)
        if (!party->SetCardNumber(user, cardNo, static_cast<eClearRewardCardType_t>(cardType)))
            return 0;
        party->SendEachCardInfo();
    }

    // +0x21a: 全员已接收 → 若全员选卡完成则推进 clear state 5 并 dungeon_clear
    if (!party->CheckRecvFromAllMember(user))
        return 0;
    if (party->IsCompleteCardSelectOfMembers(static_cast<eClearRewardCardType_t>(2)))
    {
        party->set_dungeon_clear_state(5);
        party->dungeon_clear();
    }
    return 0;
}
int Dispatcher_Select_Card::process(CUser* user, MSG_BASE& msg, ParamBase& param) { return 0; }
int Dispatcher_Select_Card::read(PacketBuf& packet, MSG_BASE& msg) { return 0; }

Dispatcher_UpgradeItem::~Dispatcher_UpgradeItem() {}
// b28d-solo-Dispatchers verdict=DIFF(routed) [N82] ORIG 0x082006d0 orig/ours=258/226 ndiff-blocks=24
//   帧差 sub $150 vs $d8 + 槽号漂移（4.1 不按 lifetime 复用栈槽）
//   首差: push   %edi | push   %ebx | sub    $0x150,%esp
// [SweepDispatchers 2026-09-09] 真缺口修复：ORIG 0x0820082c 调 get_int(unsigned long&)（Rm）
//   而旧码对 unsigned int 字段选 Rj ⇒ p167 MISSING 1；调用点改
//   reinterpret_cast<unsigned long&>(req.m_targetItemIdx) 后 CLEAR（残余仅 C1/C2 同址别名
//   P93 + 我方多 1 次 memset：ctor 内已 memset(m_28,0,0x81)，此处为重复清零，待属主裁量）。
int Dispatcher_UpgradeItem::dispatch_sig(CUser* user, PacketBuf& packet)
{
    if (user == 0 || user->CheckInTrade())
    {
        return 0;                                    // ORIG 空用户/交易中静默丢弃
    }
    if (!(user->get_state() == 3 && user->getCurCharacR() != 0))
    {
        return LineFunc(
            0x9518,
            __PRETTY_FUNCTION__,
            0, 0);
    }
    if (user->CheckInTrade())                        // ORIG 二次检查
    {
        return 0;
    }

    MSG_ITEM_UPGRADE req;                            // ORIG ctor @0x0822dcea

    if (!packet.get_byte(req.m_upgradeType))   // +0x1a byte
    {
        return LineFunc(
            0x9530,
            __PRETTY_FUNCTION__,
            0, 0);
    }
    if (!packet.get_short(req.m_targetSlot))   // +0x1b word（槽位）
    {
        return LineFunc(
            0x9532,
            __PRETTY_FUNCTION__,
            0, 0);
    }
    // ORIG 0x0820082c 调 get_int(unsigned long&)（Rm）：按 ORIG 字段宽度取重载。
    if (!packet.get_int(reinterpret_cast<unsigned long&>(req.m_targetItemIdx)))  // +0x1d dword
    {
        return LineFunc(
            0x9534,
            __PRETTY_FUNCTION__,
            0, 0);
    }
    if (!packet.get_short(req.m_materialSlot)) // +0x23 word
    {
        return LineFunc(
            0x9536,
            __PRETTY_FUNCTION__,
            0, 0);
    }
    if (!packet.get_short(req.m_ticketSlot))   // +0x21 word
    {
        return LineFunc(
            0x9539,
            __PRETTY_FUNCTION__,
            0, 0);
    }

    // ORIG 0x082008bc..0x08200957：-0x14=0x80（随后被 get_int 覆盖）、-0x18=0（dead）、
    // -0x99..-0x19 的 0x81 字节 dead 缓冲（内联对齐剥离慢路）。ORIG 无独立 memset(req+0x28)：
    // ctor 0x0822dcea 已 memset(this+0x28,0,0x81)，此处旧码的 memset 是 EXTRA（p167）。
    unsigned int strLen = 0x80;                      // ORIG -0x14
    int deadLen0 = 0;                                // ORIG -0x18（dead）
    char deadBuf[0x81] = {0};                        // ORIG -0x99..-0x19（dead）
    (void)deadLen0;
    (void)deadBuf;
    if (!packet.get_int(strLen))                     // 字符串长度前导
    {
        return LineFunc(
            0x9540,
            __PRETTY_FUNCTION__,
            0, 0);
    }
    if (!packet.get_str(req.m_28, (int)sizeof(req.m_28), (int)strLen))
    {
        return LineFunc(
            0x9542,
            __PRETTY_FUNCTION__,
            0, 0);
    }

    ServiceRestrictManager* restrictMgr = ARAD::Singleton<ServiceRestrictManager>::Get();
    if (restrictMgr->isRestricted(user, RestrictCategory::Enum_1, 7))
    {
        user->SendCmdErrorPacket2Byte((ENUM_CMDPACKET)0x53, 0xd1);
        return 0;
    }

    const unsigned int secu =
        GlobalData::s_pSecuProtectionField->Check(user, (SECURITY_PROTCTION)0x25);
    if (secu != 0)
    {
        user->SendCmdErrorPacket2Byte((ENUM_CMDPACKET)0x53,
                                      (unsigned short)(secu & 0xffff));
        return 0;
    }

    if (user->CheckItemLock(1, req.m_targetSlot))
    {
        user->SendCmdErrorPacket2Byte((ENUM_CMDPACKET)0x53, 0xd5);
        return 0;
    }

    G_CDataManager()->m_itemUpgrade->item_upgrade_system(user, &req, 0x53);
    return 0;
}
