    // 帧偏移：-0x3a=pkt+0x7(UID)、-0x37=pkt+0xa(characNo)、-0x32=pkt+0xf(30 字节名区)
    *reinterpret_cast<int*>(reinterpret_cast<char*>(&pkt) + 7) = user->GetUID();
    *reinterpret_cast<int*>(reinterpret_cast<char*>(&pkt) + 0xa) = user->getCurCharacNo();
