        return LineFunc(0x94e7,
                        __PRETTY_FUNCTION__,
                        0, 0);

    // +0x66：读数量
    if (!packet.get_byte(count))
        return LineFunc(0x94ec,
                        __PRETTY_FUNCTION__,
                        0, 0);
    // +0xaa：count > 0x5f → 拒绝
    if (count >= 0x60)
        return LineFunc(0x94f0,
                        __PRETTY_FUNCTION__,
                        0, 0);

