int Dispatcher_DenyJoinGuild::process(CUser* user, MSG_BASE& msg, ParamBase& param)
{
    // ORIG 0x81d51e6：bool deny 无槽（mov $1/$0,%eax merge test）；applicant=param+0xd→%esi、
    // guildkey→%ebx 跨 GetUID 调用（register 具名）；master/sub xor $1 直判（bool callee）。
    MSG_BASE* pm = &msg;               // ORIG 顶部死槽 -0xc（0x10(%ebp)=msg，后回读 +0xd）
    if (user->get_state() != 3)
    {
        return 0;
    }
    // ORIG 短路 && 直判形（dA 探针实证 xor1;test;je 双段 + mov $1/$0 merge test）
    if (!user->IsGuildMaster() && !user->IsSubGuildMaster())
    {
        return 0;
    }
    struct MsgView { char pad[0xd]; unsigned int applicant; } __attribute__((packed));
    // ORIG 0x081d5257: mov 0xd(%eax),%esi 单级非对齐装载（packed 视图）
    register const unsigned int applicant = reinterpret_cast<MsgView*>(pm)->applicant;
    register const int guildkey = user->get_charac_guildkey();
    DB_DenyJoinGuild::makeRequest(user->GetUID(), (unsigned int)guildkey, applicant);
    user->SendCmdOkPacket((ENUM_CMDPACKET)0x160);
    return 0;
}
int Dispatcher_DenyJoinGuild::read(PacketBuf& packet, MSG_BASE& msg)
{
    // ORIG 0x T：读 unsigned int(msg+0xd)，失败记 LineFunc(0x357f)
    char* p = reinterpret_cast<char*>(&msg);
    if (!packet.get_int(*reinterpret_cast<unsigned int*>(p + 0xd)))
    {
        return LineFunc(0x357f, __PRETTY_FUNCTION__, 0, 0);
    }
    return 0;
}

Dispatcher_EnchantByBead::~Dispatcher_EnchantByBead() {}
// b28d-solo-Dispatchers verdict=DIFF(routed) [N-P197④] ORIG 0x081d24b8 orig/ours=75/69 ndiff-blocks=9
//   ORIG setcc 物化（bool 归一岛）而 4.4 折直跳/槽化，源形不可择
//   首差: mov    0x14(%ebp),%eax | mov    %eax,-0x14(%ebp) | mov    %eax,%edx
int Dispatcher_EnchantByBead::process(CUser* user, MSG_BASE& msg, ParamBase& param)
{
    // ORIG 0x081d24b8：param+4 = check_error(...)；>0 返 0；<0 LineFunc(0x2f61,err,0)；
    // ==0 调 GlobalData::s_ExpertJobMgr->OnEnchantByBead(user, msg+0xd(char),
    // msg+0xe(short), msg+0x10(char), msg+0x12(short))，非 0 结果写回 param+4，恒返 0。
    int err = check_error(user, msg, param);
    *reinterpret_cast<int*>(reinterpret_cast<char*>(&param) + 4) = err;
    if (err > 0)
    {
        return 0;
    }
    if (err < 0)
    {
        return LineFunc(0x2f61,
                        __PRETTY_FUNCTION__,
                        err, 0);
    }
    const MSG_ENCHANT_BY_BEAD* m =
        reinterpret_cast<const MSG_ENCHANT_BY_BEAD*>(&msg);
    int result = 0;
    // asm：msg+0xd movsbl、msg+0xe movswl、msg+0x10 movsbl、msg+0x12 movswl
    result = GlobalData::s_ExpertJobMgr->OnEnchantByBead(
        user,
        static_cast<int>(m->m_field0d),
        static_cast<int>(m->m_field0e),
        static_cast<int>(m->m_field10),
        static_cast<int>(m->m_field12));
    if (result != 0)
    {
        *reinterpret_cast<int*>(reinterpret_cast<char*>(&param) + 4) = result;
    }
    return 0;
}
int Dispatcher_EnchantByBead::read(PacketBuf& packet, MSG_BASE& msg)
{
    // ORIG 0x081d2218：byte@0xd → short@0xe → byte@0x10 → short@0x12，失败逐级 LineFunc
    MSG_ENCHANT_BY_BEAD& m = reinterpret_cast<MSG_ENCHANT_BY_BEAD&>(msg);
    if (!packet.get_byte(*reinterpret_cast<char*>(&m.m_field0d)))
        return LineFunc(0x2f1c, __PRETTY_FUNCTION__, 0, 0);
    if (!packet.get_short(m.m_field0e))
        return LineFunc(0x2f1d, __PRETTY_FUNCTION__, 0, 0);
    if (!packet.get_byte(*reinterpret_cast<char*>(&m.m_field10)))
        return LineFunc(0x2f1f, __PRETTY_FUNCTION__, 0, 0);
    if (!packet.get_short(m.m_field12))
        return LineFunc(0x2f20, __PRETTY_FUNCTION__, 0, 0);
    return 0;
}
void Dispatcher_EnchantByBead::send(CUser* user, ParamBase& param)
{
    // ORIG 0x081d25b0 T：param 指针→-0xc 槽；p->m_4==0x7fffffff/0 → 不发包（je end 共享），
    // 否则 SendCmdErrorPacket(0x113, (unsigned char)p->m_4)（真值 test 形）。
    Err4ParamView* p = reinterpret_cast<Err4ParamView*>(&param);
    if (p->m_4 == (int)0x7fffffff)
        return;
    if (p->m_4)
        user->SendCmdErrorPacket((ENUM_CMDPACKET)0x113, (unsigned char)p->m_4);
}

