// b28d-solo-Dispatchers verdict=AE(routed) [S162-verify] ORIG 0x081dd87a orig/ours=21/21
int Dispatcher_ItemDictionary::check_error(CUser* user, MSG_BASE& msg)
{
    // ORIG 0x081dd880：user!=0 正向嵌套 + setle 物化（技巧9）+ msg 死槽 -0xc（技巧13 声明位）。
    // 技巧23 双 goto：4.4 需把 user==0 的 -1 岛摆在入口 cond 之后（ORIG jne BODY 形）。
    if (user != 0)
        goto LBODY;
    return -1;
LBODY:
    if ((bool)(user->get_state() <= 2))
        return 1;
    MSG_BASE* pm = &msg;
    (void)pm;
    return 0;
}
// ORIG 0x081dd7fe（报告 Dispatcher_ItemDictionary/process.md）：
// err>0 直接 0；err<0 记 LineFunc(0x4e52)；否则 0。
// b28c-L20: AE — 具名 stItemDictionary* 局部（-0x10 槽）+ 三次重读 p->m_4；
//   >0 早返 0 / <0 return LineFunc / ==0 落 msg 死槽后 return 0（P0 槽往返判读）。
int Dispatcher_ItemDictionary::process(CUser* user, MSG_BASE& msg, ParamBase& param)
{
    stItemDictionary* p = static_cast<stItemDictionary*>(&param);
    p->m_4 = check_error(user, msg);
    if (p->m_4 > 0)
        return 0;
    if (p->m_4 < 0)
        return LineFunc(0x4e52,
                        __PRETTY_FUNCTION__,
                        p->m_4, 0);
    MSG_BASE* pm = &msg;
    (void)pm;
    return 0;
}
int Dispatcher_ItemDictionary::read(PacketBuf& packet, MSG_BASE& msg)
{
    MSG_BASE* pm = &msg;   // ORIG：msg→-0x4 死槽 + sub $0x10 + leave（技巧8）
    (void)pm;
    return 0;
}
void Dispatcher_ItemDictionary::send(CUser* user, ParamBase& param)
{
    // ORIG 0x081dd8b6 T：&param 存局部，两次读 +0x04（0→OkPacket，否则 ErrorPacket）。
    stItemDictionary& p = static_cast<stItemDictionary&>(param);
    if (p.m_4 == 0)
        user->SendCmdOkPacket((ENUM_CMDPACKET)0x1b8);
    else
        user->SendCmdErrorPacket((ENUM_CMDPACKET)0x1b8, (unsigned char)p.m_4);
}

