Dispatcher_ChangeHostWarRoom::~Dispatcher_ChangeHostWarRoom() {}
int Dispatcher_ChangeHostWarRoom::check_error(CUser* user, MSG_BASE& msg)
{
    if (user == 0)
    {
        // ORIG 0x081d74f0 `movl $&_ZZ…E19__PRETTY_FUNCTION__,0x4(%esp)`（P139/P118：
        // 手写签名串 + 具名指针局部会多占 -0x14 槽并产两段装载）⇒ 直传 __PRETTY_FUNCTION__。
        return LineFunc(0x41b1, __PRETTY_FUNCTION__, 0, 0);
    }
    if (user->getCurCharacR() == 0)
    {
        return LineFunc(0x41b4, __PRETTY_FUNCTION__, 0, 0);
    }
    const MSG_CHANGE_HOST_WARROOM& req =
        reinterpret_cast<const MSG_CHANGE_HOST_WARROOM&>(msg);
    // ORIG 0x081d7549/0x081d7554：两条件各自重读 `mov -0xc,%eax; movzbl 0xd(%eax),%eax`
    // （P0/P48：无 warRoom 槽往返 ⇒ 表达式直读，禁具名局部）。
    if ((signed char)req.m_pad[0] < 0 || (signed char)req.m_pad[0] > 5)
    {
        return LineFunc(0x41b8, __PRETTY_FUNCTION__, 0, user->get_acc_id());
    }
    // ORIG 0x081d7597：`cmp $0x8,%eax; setne %al; test %al,%al; je <mov $0>`（4.1 bool
    // 物化后分支）⇒ P225 while+return 形复现；三目/裸 if 在 4.4 折成 jne 直跳。
    while (user->get_state() != 8)
        return -1;
    return 0;
}
// b28d-solo-Dispatchers verdict=DIFF(routed) [N82] ORIG 0x081d73f6 orig/ours=64/64 ndiff-blocks=14
//   帧差 sub $24 vs $38 + 槽号漂移（4.1 不按 lifetime 复用栈槽）
//   首差: push   %ebx | sub    $0x24,%esp | mov    %eax,-0x18(%ebp)
int Dispatcher_ChangeHostWarRoom::process(CUser* user, MSG_BASE& msg, ParamBase& param)
{
    int err;
    short roomIdx;
    CGameManager* mgr;
    WarRoom* room;
    int result;

    err = check_error(user, msg);
    if (err > 0)
        return err;
    if (err < 0)
        return -1;
    roomIdx = (short)user->GetWarRoomIndex();
    mgr = G_CGameManager();
    room = mgr->GetWarRoom(roomIdx);
    if (room == 0)
    {
        LineFunc(0x41a7,
                 __PRETTY_FUNCTION__,
                 0, user->get_acc_id());
    }
    else
    {
        result = room->HostChangeWarRoom(
            user,
            *(reinterpret_cast<char*>(&msg) + 0xd),
            *reinterpret_cast<unsigned long*>(reinterpret_cast<char*>(&msg) + 0xe));
        *(reinterpret_cast<int*>(&param) + 1) = result;
    }
    return 0;
}
int Dispatcher_ChangeHostWarRoom::read(PacketBuf& packet, MSG_BASE& msg)
{
    char* p = reinterpret_cast<char*>(&msg);
    if (!packet.get_byte(*reinterpret_cast<char*>(p + 0xd)))
    {
        return LineFunc(0x418e,
                        __PRETTY_FUNCTION__,
                        0, 0);
    }
    if (!packet.get_int(*reinterpret_cast<unsigned long*>(p + 0xe)))
    {
        return LineFunc(0x4191,
                        __PRETTY_FUNCTION__,
                        0, 0);
    }
    return 0;
}
void Dispatcher_ChangeHostWarRoom::send(CUser* user, ParamBase& param)
{
    // ORIG 0x38：读响应 +0x04 错误码字节，非 0 则 SendCmdErrorPacket。
    stChangeHostWarRoom& p = static_cast<stChangeHostWarRoom&>(param);
    if (p.m_4 != 0)
        user->SendCmdErrorPacket((ENUM_CMDPACKET)0x194, (unsigned char)p.m_4);
}

Dispatcher_ConnectP2PAssault::~Dispatcher_ConnectP2PAssault() {}
// b28d-solo-Dispatchers verdict=DIFF(routed) [N82] ORIG 0x08206fea orig/ours=124/128 ndiff-blocks=22
//   帧差 sub $24 vs $38 + 槽号漂移（4.1 不按 lifetime 复用栈槽）
//   首差: push   %ebx | sub    $0x24,%esp | movl   $&_ZZN28Dispatcher_ConnectP2PAssault12dispatch_sigEP5CUserR9PacketBufE19__PRETTY_FUNCTION__,0x4(%esp)
int Dispatcher_ConnectP2PAssault::dispatch_sig(CUser* user, PacketBuf& packet)
{
    if (user->get_state() <= 1)
    {
        return LineFunc(0xa1b0,
                        __PRETTY_FUNCTION__,
                        0, 0);
    }
    char count = -1;                                       // -0xd（local_19[8]）
    if (!packet.get_byte(count))
    {
        return LineFunc(0xa1b4,
                        __PRETTY_FUNCTION__,
                        0, 0);
    }
    if (count > 8 || count < 0)
    {
        return LineFunc(0xa1b8,
                        __PRETTY_FUNCTION__,
                        0, 0);
    }
    char slots[8];                                         // -0x15..-0xe（base -0x15）
    slots[0] = 0; slots[1] = 0; slots[2] = 0; slots[3] = 0;
    slots[4] = 0; slots[5] = 0; slots[6] = 0; slots[7] = 0;
    char team = -1;                                        // -0x16（local_1a）
    for (int i = 0; i < (int)count; i++)
    {
        if (!packet.get_byte(team))
        {
            return LineFunc(0xa1bf,
                            __PRETTY_FUNCTION__,
                            0, 0);
        }
        if (team > 7 || team < 0)
        {
            return LineFunc(0xa1c2,
                            __PRETTY_FUNCTION__,
                            0, 0);
        }
        if (!packet.get_byte(slots[(int)team]))
        {
            return LineFunc(0xa1c5,
                            __PRETTY_FUNCTION__,
                            0, 0);
        }
    }
    pvp_assault::CAssaultMgr* mgr = pvp_assault::GetInstanceAssaultMgr();   // 0x082350a0
    // X2 形（Main 批准铺池，OPMC8/我 probe px2 t8/t11 双实证）：绑 %eax 的具名
    // unsigned char + 显式 ^= 1 ⇒ 复现 ORIG `xor $0x1,%eax; testb %al,%al` 单段；
    // 写 `!= 1` 会被 4.4 折成 `cmpb $1` + setne 两段。
    unsigned char p2pBad =
        (unsigned char)mgr->OnConnectP2P(user, slots, (int)count);
    p2pBad ^= 1;
    if (p2pBad)
    {
        return LineFunc(0xa1cb,
                        __PRETTY_FUNCTION__,
                        0, 0);
    }
    return 0;
}

