Dispatcher_SaveCharacterOption::~Dispatcher_SaveCharacterOption() {}
int Dispatcher_SaveCharacterOption::check_error(CUser* user, MSG_BASE& msg)
{
    if (user == 0)
    {
        return -1;
    }
    if (user->get_state() < 2)
    {
        return -2;
    }
    if ((bool)(user->getCurCharacNo() == 0))   // 同上：sete 物化保形
        return -3;
    return 0;
}
// ORIG 0x081ce97c（报告 Dispatcher_SaveCharacterOption/process.md）：
// param+4=check_error；>0 → 0；<0 LineFunc(0x283d)；==0 setSaveCharacOption(true)
// + SetCurCharacOption(msg+0x11)。
int Dispatcher_SaveCharacterOption::process(CUser* user, MSG_BASE& msg, ParamBase& param)
{
    // ORIG 0x081ce97c 序言：`mov 0x14(%ebp),%eax; mov %eax,-0x10(%ebp)` ⇒ param 指针
    // **函数头即落槽**（P0 槽往返），其后所有条件读回的都是 `param+4`（无独立 err 槽：
    // call 结果经 `mov %eax,%edx` 直存 disp）。裸偏移 +4 改具名 pack(1) 视图（§4.3）。
    struct __attribute__((packed)) SaveCharacOptParamView
    {
        char m_head[4];
        int m_err;                // +0x04
    };
    SaveCharacOptParamView* const p =
        reinterpret_cast<SaveCharacOptParamView*>(&param);
    p->m_err = check_error(user, msg);
    if (p->m_err > 0)
    {
        return 0;
    }
    // ORIG 0x081ce9xx：err<0 块在前（`test; jns` 越过），两臂汇入**共享尾 return**
    // （4.4 对独立早返恒就地物化 `mov $0,%eax` ⇒ 用 if/else 而非二次 return）。
    if (p->m_err < 0)
    {
        LineFunc(0x283d,
                 __PRETTY_FUNCTION__,
                 p->m_err, (unsigned int)user->get_acc_id());
    }
    else
    {
        // ORIG 0x081ce9xx：msg 指针槽 -0xc 在 setSaveCharacOption **之前**物化
        // ⇒ req 引用声明前置（4.4 在绑定处落槽）。
        MSG_SAVE_CHARACTER_OPTION& req =
            reinterpret_cast<MSG_SAVE_CHARACTER_OPTION&>(msg);
        user->setSaveCharacOption(true);
        user->SetCurCharacOption(req.m_option);        // +0x11 CharacterOption
    }
    return 0;
}
// b28d-solo-Dispatchers verdict=DIFF(routed) [N96] ORIG 0x081ce8bc orig/ours=51/54 ndiff-blocks=6
//   P0 清绑：原 `register asm("reg")` 存量绑定已删（N96 全域禁绑，不得恢复）；
//   清绑后残余寄存器/槽序差按 N96+N18a 封顶（实测内联/unsigned 化等自然形不闭合）。
//   首差: mov    %eax,-0xc(%ebp) | mov    -0xc(%ebp),%eax | mov    -0xc(%ebp),%eax
int Dispatcher_SaveCharacterOption::read(PacketBuf& packet, MSG_BASE& msg)
{
    // ORIG 0x081ce8bc：同 SaveGameOption_1/2 混合形——typed 指针槽 -0xc、
    // get_int 实参 add $0xd、len typed 单级回读。MSG 头 +0xd 无具名字段
    //（PacketTypes.h 冻结），本 TU 局部视图承接。视图须 packed：ORIG 回读形
    // `mov 0xd(%eax),%eax`（+0x0d 起 len），默认对齐会把 m_len 推到 +0x10。
    struct __attribute__((packed)) SaveCharacOptView {
        char m_head[0xd];
        unsigned int m_len;      // +0x0d
    };
    SaveCharacOptView* m = reinterpret_cast<SaveCharacOptView*>(&msg);
    if (!packet.get_int(*reinterpret_cast<int*>(reinterpret_cast<char*>(m) + 0xd)) ||
        m->m_len >= 0x201)
        return LineFunc(0x2829, __PRETTY_FUNCTION__, 0, 0);
    // [b28d-solo-Dispatchers] P0：ORIG 无 lv/pbuf 槽 ⇒ 删具名局部改内联实参
    //   （同 SGO_2 形，右→左求值先 len 后 buf）。
    // [b28d-solo-Dispatchers] P319：buf 实参整型加法 + 回 cast（探针 probe_gb2 d）。
    if (!packet.get_binary(
            reinterpret_cast<char*>(reinterpret_cast<unsigned int>(m) + 0x11),
            (int)m->m_len))
        return LineFunc(0x282b, __PRETTY_FUNCTION__, 0, 0);
    return 0;
}

Dispatcher_SecretShopOpenClose::~Dispatcher_SecretShopOpenClose() {}
// b28d-solo-Dispatchers verdict=DIFF(routed) [N82] ORIG 0x081d28b4 orig/ours=66/62 ndiff-blocks=11
//   帧差 sub $24 vs $28 + 槽号漂移（4.1 不按 lifetime 复用栈槽）
//   首差: push   %ebx | sub    $0x24,%esp | mov    0x14(%ebp),%eax
int Dispatcher_SecretShopOpenClose::process(CUser* user, MSG_BASE& msg, ParamBase& param)
{
    // ORIG 0x081d28b4：check_error(三参) 结果写 param+0x04；
    // err>0 → 0；err<0 → LineFunc(0x2fdc)；err==0 → 设置/清除秘密商店购买位。
    int err = check_error(user, msg, param);
    *(int*)(reinterpret_cast<char*>(&param) + 0x4) = err;

    if (err > 0)
    {
        return 0;
    }
    if (err < 0)
    {
        LineFunc(0x2fdc,
                 __PRETTY_FUNCTION__,
                 err, 0);
        return 0;
    }

    void* shopData = user->GetSecretShopData();
    if (shopData == 0)
    {
        *(int*)(reinterpret_cast<char*>(&param) + 0x4) = 0x7fffffff;
        return 0;
    }

    // msg+0xd：购买开关字节（非 0 → true）。
    bool buy =
        *reinterpret_cast<unsigned char*>(reinterpret_cast<char*>(&msg) + 0xd) != 0;
    int pos = user->GetUserPosInParty();
    reinterpret_cast<secretshop::SECRET_SHOP_DATA*>(shopData)->SetBuying(pos, buy);
    return 0;
}
int Dispatcher_SecretShopOpenClose::read(PacketBuf& packet, MSG_BASE& msg)
{
    // ORIG 0x T：读 char(msg+0xd)，失败记 LineFunc(0x2fc4)
    char* p = reinterpret_cast<char*>(&msg);
    if (!packet.get_byte(*reinterpret_cast<char*>(p + 0xd)))
    {
        return LineFunc(0x2fc4, __PRETTY_FUNCTION__, 0, 0);
    }
    return 0;
}
void Dispatcher_SecretShopOpenClose::send(CUser* user, ParamBase& param)
{
    (void)user;
    // ORIG 0x19：读 +0x04 与 0x7fffffff 比较，条件真则提前返回（无副作用）。
    stSecretShopOpenCloseParam& p = static_cast<stSecretShopOpenCloseParam&>(param);
    if (p.m_4 == 0x7fffffff)
        return;
}

Dispatcher_SecurityCardAuthReq::~Dispatcher_SecurityCardAuthReq() {}
// b28d-solo-Dispatchers verdict=DIFF(routed) [N82] ORIG 0x0820a2c4 orig/ours=90/96 ndiff-blocks=7
//   帧差 sub $18 vs $28 + 槽号漂移（4.1 不按 lifetime 复用栈槽）
//   首差: sub    $0x18,%esp | movl   $&_ZZN30Dispatcher_SecurityCardAuthReq12dispatch_sigEP5CUserR9PacketBufE19__PRETTY_FUNCTION__,0x4(%esp) | seta   %al
int Dispatcher_SecurityCardAuthReq::dispatch_sig(CUser* user, PacketBuf& packet)
{
    // ORIG 0x0820a2c4
    // ORIG cmp $0x2,get_state; setle → state<=2 走断言
    if (user->get_state() <= 2)
    {
        return LineFunc(0xa5fd,
                        __PRETTY_FUNCTION__,
                        0, 0);
    }

    // card.isActivate() || pad.isActivate()
    // ORIG 0x0820a316..0x0820a344：短路 `||` 物化为 `jne L_true / je L_false /
    // mov $1 / jmp / mov $0 / test %al,%al; je <尾部失败块>`，且汇聚值**无栈槽往返**
    // （P0）⇒ 具名 bool 必顶槽（帧 0x18→0x28）。改 P226 扩展：语句表达式包住整个条件
    // （内无具名变量）+ 正极性包裹，失败块归函数尾（P214① 负极性恒 je/jne 反演）。
    if (({ user->getSecurityCard()->isActivate() ||
           user->getPad()->isActivate(); }))
    {
        if (user->getSecurityCard()->isActivate())
        {
            // T1/T2 直证：ORIG 0x0820a36c `cmp $0x2,%eax; seta` ⇒ 无符号比较。
            if ((unsigned int)user->getSecurityCard()->getFailCnt() > 2)
            {
                user->SendCmdErrorPacket((ENUM_CMDPACKET)0xa6, 0x7a);
                return 0;
            }
        }
        else
        {
            if (user->getPad()->getFailCnt() > 2)        // ORIG cmp $0x2; setg
            {
                user->SendCmdErrorPacket((ENUM_CMDPACKET)0xa6, 0x88);
                return 0;
            }
        }

        // ORIG：Check 返回值丢弃，恒 return 0
        GlobalData::s_pSecuProtectionField->Check(user, (SECURITY_PROTCTION)0);
        return 0;
    }
    return LineFunc(0xa625,
                    __PRETTY_FUNCTION__,
                    0, 0);
}
int Dispatcher_SecurityCardAuthReq::process(CUser* user, MSG_BASE& msg, ParamBase& param) { return 0; }
int Dispatcher_SecurityCardAuthReq::read(PacketBuf& packet, MSG_BASE& msg) { return 0; }


Dispatcher_SecurityCardCertKey::~Dispatcher_SecurityCardCertKey() {}
// b28d-solo-Dispatchers verdict=DIFF(routed) [N-P112] ORIG 0x0820a6bc orig/ours=173/182 ndiff-blocks=21
//   残余为跨版本寄存器分配/栈槽序差（P75/P112 结构性），语义已对齐
//   首差: movl   $&_ZZN30Dispatcher_SecurityCardCertKey12dispatch_sigEP5CUserR9PacketBufE19__PRETTY_FUNCTION__,0x4(%esp) | movl   $0x0,-0x10(%ebp) | movl   $0x0
int Dispatcher_SecurityCardCertKey::dispatch_sig(CUser* user, PacketBuf& packet)
{
    // ORIG 0x0820a6bc（docs/class_func_reports/Dispatcher_SecurityCardCertKey/dispatch_sig.md）
    char certKey[6];                          // local_1a -0x16
    unsigned int keyLen = 0;                  // local_14 -0x10
    int idx;                                  // local_10 -0xc

    // +0x00：state < 3 → 拒绝
    if (user->get_state() < 3)
        return LineFunc(0xa675,
                        __PRETTY_FUNCTION__,
                        0, 0);

    // +0x46：清零
    keyLen = 0;
    memset(certKey, 0, 6);

    // +0x5a：读长度与 6 位认证码
    if (!packet.get_int((unsigned int&)keyLen))
        return LineFunc(0xa681,
                        __PRETTY_FUNCTION__,
                        0, 0);
    if (!packet.get_str(certKey, 6, keyLen))
        return LineFunc(0xa683,
                        __PRETTY_FUNCTION__,
                        0, 0);

    // +0xed：已激活且认证标志已开 → 拒绝
    if (user->getSecurityCard()->isActivate()
        && user->getSecurityCard()->isCertFlagOn())
        return LineFunc(0xa688,
                        __PRETTY_FUNCTION__,
                        0, 0);
    // +0x144：已认证 → 拒绝
    if (user->getSecurityCard()->isCertified())
        return LineFunc(0xa68c,
                        __PRETTY_FUNCTION__,
                        0, 0);

    // +0x184：前 5 位必须为数字（'0'..'9'；ORIG 为 movsbl 减 0x30 后无符号 ≤9 判定）
    for (idx = 0; idx <= 4; idx = idx + 1)
    {
        if ((unsigned int)((int)(signed char)certKey[idx] - 0x30) > 9)
            return LineFunc(0xa691,
                            __PRETTY_FUNCTION__,
                            0, 0);
    }

    // +0x1da：行为日志（action：未激活=2、已激活=3）
    if (!user->getSecurityCard()->isActivate())
        user->m_historyLog.SecuService((ENUM_SECU_SERVICE_TYPE)1, (ENUM_SECU_SERVICE_ACTION)2);
    else
        user->m_historyLog.SecuService((ENUM_SECU_SERVICE_TYPE)1, (ENUM_SECU_SERVICE_ACTION)3);

    // +0x233：Hades 安全等级切换（1=ENUM_HADES_SECURITY；value：未激活=0x1a、已激活=0x1b）
    if (!user->getSecurityCard()->isActivate())
        ((XNuclear::CHades*)user->getHades())->ChangeSecurity((XNuclear::ENUM_HADES_SECURITY)1, 0x1a);
    else
        ((XNuclear::CHades*)user->getHades())->ChangeSecurity((XNuclear::ENUM_HADES_SECURITY)1, 0x1b);

    // +0x292：DB 激活请求
    DB_SecurityCardActivate::makeRequest((unsigned int)user->GetUID(),
                                         user->get_acc_id(),
                                         certKey,
                                         user->getSecurityCard()->isActivate());
    return 0;
}
int Dispatcher_SecurityCardCertKey::process(CUser* user, MSG_BASE& msg, ParamBase& param) { return 0; }
int Dispatcher_SecurityCardCertKey::read(PacketBuf& packet, MSG_BASE& msg) { return 0; }

Dispatcher_UpdateServerMessage::~Dispatcher_UpdateServerMessage() {}
// b28d-solo-Dispatchers verdict=DIFF(routed) [N82] ORIG 0x0821d9ee orig/ours=345/329 ndiff-blocks=61
//   帧差 sub $b0 vs $d0 + 槽号漂移（4.1 不按 lifetime 复用栈槽）
//   首差: sub    $0xb0,%esp | mov    %eax,%ebx
int Dispatcher_UpdateServerMessage::dispatch_sig(CUser* user, PacketBuf& packet)
{
    // ORIG 0x0821d9ee..0x0821df69 (0x57c 字节)。

    if (user->get_state() != 3)
    {
        // [b28d-solo-Dispatchers] P227/P0：ORIG 0x0821d9ee 段在 cMyTrace ctor 前
        //   求值 varargs 并跨 ctor 以 %ebx/%esi 保活（`call get_acc_id;
        //   movl $0,0x4(%esp); mov %eax,(%esp); call NumberToString; mov %eax,%ebx;
        //   call get_state; mov %eax,%esi; call cMyTraceC1; …`），**无** accId/idStr
        //   具名槽 ⇒ 全表达式临时链（旧码两局部使帧 +8）。
        cMyTrace(__PRETTY_FUNCTION__, 0xd1c6, 0)(
            "ServerMessage : Dispatcher_UpdateServerMessage => User State : %d, m_id : %s",
            user->get_state(), NumberToString(user->get_acc_id(), 0));
        return LineFunc(0xd1c7, __PRETTY_FUNCTION__, 0, 0);
    }

    PacketGuard guard;
    guard.put_header(1, 0xdd);

    unsigned char msgIdx = 0;
    if (packet.get_byte(msgIdx) != 1)
    {
        return LineFunc(0xd1d0, __PRETTY_FUNCTION__, 0, 0);
    }
    int titleLen = 0;
    if (packet.get_int(titleLen) != 1)
    {
        return LineFunc(0xd1d5, __PRETTY_FUNCTION__, 0, 0);
    }

    if (titleLen < 0 || 0x31 < titleLen)
    {
        guard.put_byte(0);
        guard.put_byte(1);
        guard.finalize(true);
        user->Send(guard);
        return 0;
    }

    char title[50];   // -0x8e，0x32
    if (packet.get_str(title, 0x32, titleLen) != 1)
    {
        return LineFunc(0xd1e4, __PRETTY_FUNCTION__, 0, 0);
    }
    if (G_CDataManager()->hasPreventString(title))
    {
        guard.put_byte(0);
        guard.put_byte(0x17);
        guard.finalize(true);
        user->Send(guard);
        return 0;
    }

    int contentLen = 0;
    if (packet.get_int(contentLen) != 1)
    {
        return LineFunc(0xd1f4, __PRETTY_FUNCTION__, 0, 0);
    }

    // [Lane1Dispatchers 2026-09-10] N78/P214③：ORIG 0x0821dcd3-0x0821dd22 是
    //   `memset(content,0,0x1e)` 的 4.1 **内联**对齐剥离慢路（起始 `and $0x2` =
    //   地址 ≡2 mod 4，与 -0x56 相符）；我方 `memset` 在 4.4 -O0 恒退化为
    //   `call memset`（多 3 条 + 丢 30 条形）。改聚合初始化 `= {0}` 即复现慢路。
    char content[30] = {0};   // -0x56，0x1e
    // [b28d-solo-Dispatchers] 语义修正（Main 新判据②回边核对命中）：ORIG
    //   0x0821dcd3-0x0821dd22 是 `memset(content,0,0x1e)` 的 4.1 **内联慢路**展开
    //   （`lea -0x56(%ebp),%eax; mov $0x1e,%ebx; …and $2…; mov %edx,(%eax,%ecx,1);
    //   add $0x4,%ecx; cmp %esi,%ecx; jb`+尾 2/1 字节），即 ORIG **有**清零。
    //   第一波据 p167 EXTRA `memset`+1 误判「ORIG 无清零」而删除 ⇒ 丢失语义
    //   （get_str 短串时 strcmp 读未初始化尾部）⇒ 恢复 memset。
    if (packet.get_str(content, 0x1e, contentLen) != 1)
    {
        return LineFunc(0xd1f9, __PRETTY_FUNCTION__, 0, 0);
    }

    if (strcmp(content, user->getCurCharacName()) != 0)
        return LineFunc(0xd1fd, __PRETTY_FUNCTION__, 0, 0);

    const int curSec = GlobalData::s_systemTime_.getCurSec();
    CSharedServerMessageManager* mgr = G_CGameManager()->GetSharedServerMessageManager();
    if (mgr != 0)
    {
        int condResult = 0;
        if (!mgr->CheckUserCondition(user, (int)msgIdx, condResult))
        {
            guard.put_byte(0);
            if (condResult == 0)
                guard.put_byte(3);
            else
                guard.put_byte(condResult);
        }
        else if (!mgr->IsChangableMessage((int)msgIdx, curSec))
        {
            guard.put_byte(0);
            guard.put_byte(1);
        }
        else
        {
            mgr->UpdateServerMessage(user, (int)msgIdx, title, content, curSec);
            guard.put_byte(1);
        }
    }
    guard.put_byte((int)msgIdx);
    guard.finalize(true);
    user->Send(guard);
    return 0;
}
