int Dispatcher_WarRoomWpPerMonster::check_error(CUser* user, MSG_BASE& msg)
{
    // ORIG 0x081d5e1c：帧 0x18——pretty 直传无指针槽（具名 pretty 局部=
    // -0xc 槽膨胀，技巧36）；尾 state!=8 走 bool 物化 `setne;test;je`（技9/19）。
    if (user == 0)
    {
        return LineFunc(0x39af, __PRETTY_FUNCTION__, 0, 0);
    }
    if (user->getCurCharacR() == 0)
    {
        return LineFunc(0x39b2, __PRETTY_FUNCTION__, 0, 0);
    }
    if ((bool)(user->get_state() != 8))
    {
        return -1;
    }
    return 0;
}
// b28d-solo-Dispatchers verdict=DIFF(routed) [N-P112] ORIG 0x081d5ca8 orig/ours=89/88 ndiff-blocks=13
//   残余为跨版本寄存器分配/栈槽序差（P75/P112 结构性），语义已对齐
//   首差: mov    %eax,-0x1c(%ebp) | cmpl   $0x0,-0x1c(%ebp) | mov    -0x1c(%ebp),%eax
int Dispatcher_WarRoomWpPerMonster::process(CUser* user, MSG_BASE& msg, ParamBase& param)
{
    MSG_WARROOM_WP_PER_MONSTER& mref = reinterpret_cast<MSG_WARROOM_WP_PER_MONSTER&>(msg);  // 裸偏移→具名字段（同偏移同宽度）
    // ORIG 0x081d5ca8
    int err = check_error(user, msg);
    if (err > 0)
    {
        return err;
    }
    if (err < 0)
    {
        return -1;
    }

    // ORIG GetWarRoomIndex → movswl（short）→ CGameManager::GetWarRoom(int)
    short warRoomIndex = user->GetWarRoomIndex();
    WarRoom* warRoom = G_CGameManager()->GetWarRoom((int)warRoomIndex);
    if (warRoom == 0)
    {
        return LineFunc(0x3999,
                        __PRETTY_FUNCTION__,
                        0, user->get_acc_id());
    }

    CUser* target = 0;
    if (mref.m_killerUid != 0xffff)   // ORIG movzwl 0x15; cmp $0xffff
    {
        target = G_GameWorld()->find_from_world(mref.m_killerUid);
        if (target == 0)
        {
            return LineFunc(0x39a4,
                            __PRETTY_FUNCTION__,
                            0, user->get_acc_id());
        }
    }

    *(int*)((char*)&param + 4) = warRoom->HandleWpPerMonster(
        user,
        mref.m_field0d,
        mref.m_field11,
        target);
    return 0;
}
int Dispatcher_WarRoomWpPerMonster::read(PacketBuf& packet, MSG_BASE& msg)
{
    // ORIG 0x081d5bcc：int@0xd → int@0x11 → ushort@0x15
    MSG_WARROOM_WP_PER_MONSTER& m =
        reinterpret_cast<MSG_WARROOM_WP_PER_MONSTER&>(msg);
    if (!packet.get_int(m.m_field0d))
        return LineFunc(0x397d, __PRETTY_FUNCTION__, 0, 0);
    if (!packet.get_int(m.m_field11))
        return LineFunc(0x3980, __PRETTY_FUNCTION__, 0, 0);
    if (!packet.get_short(m.m_killerUid))
        return LineFunc(0x3983, __PRETTY_FUNCTION__, 0, 0);
    return 0;
}
void Dispatcher_WarRoomWpPerMonster::send(CUser* user, ParamBase& param)
{
    // ORIG 0x38：读响应 +0x04 错误码字节，非 0 则 SendCmdErrorPacket。
    stWarRoomWp& p = static_cast<stWarRoomWp&>(param);
    if (p.m_4 != 0)
        user->SendCmdErrorPacket((ENUM_CMDPACKET)0x179, (unsigned char)p.m_4);
}

