    else
        moveCnt = (unsigned int)((double)(unsigned long long)moveCnt * 0.8);

    if (limitCnt < moveCnt)
    {
        if (!inPowerWar)
            user->getHackAnalyzer()->addServerHackCnt(
                user, (WongWork::ENUM_HACKTYPE)0x79, 1, moveCnt, 0);
        else
            user->getHackAnalyzer()->addServerHackCnt(
                user, (WongWork::ENUM_HACKTYPE)0x7b, 1, moveCnt, 0);
    }
    return 0;
