    {
        return LineFunc(0xa6b2,
                        __PRETTY_FUNCTION__,
                        0, 0);
    }
    if (!GlobalData::s_securityCardCenter->checkPhoneNumber(phoneBuf))
    {
        return LineFunc(0xa6b5,
                        __PRETTY_FUNCTION__,
                        0, 0);
    }
