// b22 桥清零（P201，Model22）：WongWork::CItemUpgrade::ProcUpgrade 原 extern"C"
// mangled 直连桥转真成员调用。CDataManager.h:3024 权威虚槽声明、定义
// CItemUpgrade.cpp:410；ORIG 0x081d3808 调用即 devirt 直调 call 同 mangled，
// 真调用同形。

// b28d-solo-Dispatchers verdict=DIFF(routed) [N-P112] ORIG 0x081d343a orig/ours=127/125 ndiff-blocks=3
//   残余为跨版本寄存器分配/栈槽序差（P75/P112 结构性），语义已对齐
//   首差: mov    &_ZN10GlobalData22s_pSecuProtectionFieldE,%eax | mov    0x15(%eax),%eax | mov    %eax,%ebx
int Dispatcher_Enchant_3rdChronicleItem::check_error(CUser* user, MSG_BASE& msg)
{
    // [b28c-34] N18a 封顶：ORIG 0x081d34f2 段 `mov 0x15(%eax),%eax; mov %eax,%ebx;
    // call G_CDataManager` 为 4.1 两段（load→regmove 到 callee-saved）；4.4 恒折
    // 单段 `mov 0x15(%eax),%ebx`（差 1 条，后续全偏移 -2）。源侧具名局部/cast/
    // 语句表达式均不产两段（N18a 反向不可造）。语义等价。
    // 仅允许 state==3 且当前角色有效；否则错误码 7
    if (!(user->get_state() == 3 && user->getCurCharacR() != 0))
    {
        return 7;
    }

    MSG_ENCHANT& req = reinterpret_cast<MSG_ENCHANT&>(msg);

    const int secu =
        GlobalData::s_pSecuProtectionField->Check(user, (SECURITY_PROTCTION)0x27);
    if (secu != 0)
    {
        return secu;
    }

    if (user->CheckItemLock(1, (unsigned short)req.m_0d))
    {
        return 0xd5;
    }

    // msg+0x15：请求强化的物品 idx → 物品脚本必须存在
    // [b28d-solo-Dispatchers] P211 档③/P254：ORIG 0x081d34e2 `mov 0x15(%eax),%eax;
    //   mov %eax,%ebx`（两段）为「视图字段 unsigned + find_item(int) 形参异型」
    //   的转换中转形；改用 unsigned 视图字段内联实参（探针 /tmp/probe_disp.cpp t3）。
    struct __attribute__((packed)) EnchantReqView
    {
        char m_head15[0x15];
        unsigned int m_itemIdx;       // +0x15
    };
    CItem* itemScript = G_CDataManager()->find_item(
        reinterpret_cast<const EnchantReqView&>(req).m_itemIdx);
    if (itemScript == 0)
    {
        return 4;
    }

    CInventory* invenW = user->getCurCharacInvenW();
    if (invenW == 0)
    {
        return 4;
    }

    // ORIG Inven_Item ctor @0x080cb854 后整体拷贝 GetInvenSlot 结果
    Inven_Item slotItem;
    slotItem = invenW->GetInvenSlot(INVEN_TYPE_EQUIP, (unsigned short)req.m_13);

    // 背包槽内物品须与请求脚本一致，否则 0x17
    if (slotItem.m_addInfo != itemScript->get_index())
    {
        return 0x17;
    }
    return 0;
}
// b28d-solo-Dispatchers verdict=DIFF(routed) [N-P197④] ORIG 0x081d375e orig/ours=85/81 ndiff-blocks=15
//   ORIG setcc 物化（bool 归一岛）而 4.4 折直跳/槽化，源形不可择
//   首差: mov    %eax,-0x18(%ebp) | cmpl   $0x0,-0x18(%ebp) | mov    -0x18(%ebp),%eax
int Dispatcher_Enchant_3rdChronicleItem::process(CUser* user, MSG_BASE& msg, ParamBase& param)
{
    const int err = check_error(user, msg);
    if (err > 0)
    {
        user->SendCmdErrorPacket((ENUM_CMDPACKET)0x173, (unsigned char)(err & 0xff));
        return -1;
    }

    stEnchantParam& out = static_cast<stEnchantParam&>(param);   // +0x04 结果槽
    MSG_ENCHANT& req = reinterpret_cast<MSG_ENCHANT&>(msg);

    PacketGuard pg;                                              // try 域 @081d37e3..081d3846
    pg.put_header(1, 0x173);

    out.m_4 = G_CDataManager()->m_itemUpgrade->ProcUpgrade(user, &req, &pg);

    if (out.m_4 == 0)
    {
        pg.finalize(true);
        user->Send(pg);
    }
    return 0;
}
int Dispatcher_Enchant_3rdChronicleItem::read(PacketBuf& packet, MSG_BASE& msg)
{
    // ORIG 0x081d3630（报告 Dispatcher_Enchant_3rdChronicleItem/read.md）：
    // 无具名引用槽——每处 `mov 0x10(%ebp),%eax` 直读参数（帧 0x18）。
    // 具名引用中转变量=4.4 多 1 个 4B 槽⇒删中转改 cast 内联（技巧36/37）。
    if (!packet.get_short(*reinterpret_cast<unsigned short*>(
            &reinterpret_cast<MSG_ENCHANT&>(msg).m_13)))
    {
        return LineFunc(
            0x3158,
            __PRETTY_FUNCTION__,
            0, 0);
    }
    if (!packet.get_int(*reinterpret_cast<unsigned long*>(
            &reinterpret_cast<MSG_ENCHANT&>(msg).m_15)))
    {
        return LineFunc(
            0x315a,
            __PRETTY_FUNCTION__,
            0, 0);
    }
    if (!packet.get_short(*reinterpret_cast<unsigned short*>(
            &reinterpret_cast<MSG_ENCHANT&>(msg).m_0d)))
    {
        return LineFunc(
            0x315d,
            __PRETTY_FUNCTION__,
            0, 0);
    }
    if (!packet.get_int(*reinterpret_cast<unsigned long*>(
            &reinterpret_cast<MSG_ENCHANT&>(msg).m_0f)))
    {
        return LineFunc(
            0x315f,
            __PRETTY_FUNCTION__,
            0, 0);
    }
    if (!packet.get_byte(reinterpret_cast<MSG_ENCHANT&>(msg).m_19))
    {
        return LineFunc(
            0x3162,
            __PRETTY_FUNCTION__,
            0, 0);
    }
    return 0;
}
void Dispatcher_Enchant_3rdChronicleItem::send(CUser* user, ParamBase& param)
{
    stEnchantParam& out = static_cast<stEnchantParam&>(param);
    if (out.m_4 != 0)
    {
        user->SendCmdErrorPacket((ENUM_CMDPACKET)0x173,
                                 (unsigned char)(out.m_4 & 0xff));
    }
    return;   // ORIG 0x081d3880: call 后 jmp merge + nop 尾岛（技巧7）
}

