        local_38("Dispatcher_UseCreatureEvolutionItem cur_creatureid(%d) != item_base_creature_id(%d) charac_no(%d)\n",
                 user->getCurCharacInvenW()->GetCreatureMgrW()->GetCreatureIndex(),
                 stackable->m_int360, user->getCurCharacNo());
