// ORIG 0x081dff32（报告 Dispatcher_TournamentRewardSelectState/check_error.md）：
// state!=5 → 0x7fffffff；GetParty(GetPartyIndex)==0 → -1；
// TournamentDungeonClearState!=1 → 0x7fffffff；!CheckRecvFromAllMember → 0x7fffffff。
// b28d-solo-Dispatchers verdict=AE(routed) [S206 翻正] ORIG 0x081dff32
//   [N82→P200] 根因=具名 int partyIdx 落 -0x10 槽（帧 0x24→0x28）+ 缺 user==0 判空；
//   改 GetPartyIndex() 内联实参（movswl→%ebx 跨 call）+ 补判空 ⇒ 归零。
int Dispatcher_TournamentRewardSelectState::check_error(CUser* user, MSG_BASE& msg)
{
    (void)msg;
    // [b28d-solo-S206] ORIG 0x081dff32 首条 `cmpl $0x0,0xc(%ebp); jne; mov $0x7fffffff`
    //   （user==0 判空）。
    if (user == 0)
    {
        return 0x7fffffff;
    }
    if (user->get_state() != 5)
    {
        return 0x7fffffff;
    }
    // [b28d-solo-S206] P200：ORIG 0x081dff4x `call GetPartyIndex; movswl %ax,%ebx;
    //   call G_CGameManager; … mov %ebx,0x4(%esp)`（短整拓宽直传实参、跨 callee-saved
    //   保活，无栈槽）。具名 int 局部 partyIdx 使 4.4 落 -0x10 槽并帧 0x24→0x28。
    CParty* party = G_CGameManager()->GetParty(user->GetPartyIndex());
    if (party == 0)
    {
        return -1;
    }
    if (party->GetTournamentDungeonClearState() != 1)
    {
        return 0x7fffffff;
    }
    if (!party->CheckRecvFromAllMember(user))
    {
        return 0x7fffffff;
    }
    return 0;
}
// b28d-solo-Dispatchers verdict=DIFF(routed) [N-P112] ORIG 0x081dfca2 orig/ours=58/64 ndiff-blocks=8
//   残余为跨版本寄存器分配/栈槽序差（P75/P112 结构性），语义已对齐
//   首差: mov    %eax,-0x10(%ebp) | mov    -0x10(%ebp),%edx | mov    %eax,0x4(%edx)
int Dispatcher_TournamentRewardSelectState::process(CUser* user, MSG_BASE& msg, ParamBase& param)
{
    // ORIG 0x081dfca2
    stTournamentRewardSelectState& p = static_cast<stTournamentRewardSelectState&>(param);
    *(int*)((char*)&p + 4) = check_error(user, msg);
    if (*(int*)((char*)&p + 4) >= 1)
    {
        return 0;
    }
    if (*(int*)((char*)&p + 4) < 0)
    {
        return LineFunc(0x52af,
                        __PRETTY_FUNCTION__,
                        *(int*)((char*)&p + 4), 0);
    }
    int partyIndex = user->GetPartyIndex();
    CParty* party = G_CGameManager()->GetParty(partyIndex);
    if (party == 0)
    {
        return LineFunc(0x52b4,
                        __PRETTY_FUNCTION__,
                        0, (unsigned int)user->get_acc_id());
    }
    return 0;
}
int Dispatcher_TournamentRewardSelectState::read(PacketBuf& packet, MSG_BASE& msg) { return 0; }
void Dispatcher_TournamentRewardSelectState::send(CUser* user, ParamBase& param)
{
    // [b23S3C] ORIG 0x081dfd74：param 引用槽(-0x14) put_header 后回读判定（P0 无值槽，
    // 去 m_4 hoist；PacketTypes.h 冻结故用局部 overlay）；get_user 每用点重取
    // （ORIG 3 次 call），==0 call 结果直比出 test;sete;test;je（P197④）；f1 升格
    // %ebx + `cmp %ax,%bx`（P197②/P200）。GetPartyIndex movswl%ax,%ebx 已同形保留。
    struct TRSS { ParamBase hdr; int m_4; };
    TRSS& out = *reinterpret_cast<TRSS*>(&param);
    PacketGuard packet;
    packet.clear();
    packet.put_header(1, 0x1ca);
    if (out.m_4 == 0)
    {
        packet.put_byte(1);
        CParty* party = G_CGameManager()->GetParty((int)(short)user->GetPartyIndex());
        if (party != 0)
        {
            for (int i = 0; i < 4; ++i)
            {
                if (party->get_user(i) == 0)
                {
                    packet.put_byte(-1);
                }
                else if (party->get_user(i)->getCurCharacTotalFatigue() ==
                         party->get_user(i)->getCurCharacTotalMaxFatigue())
                {
                    packet.put_byte(0);
                }
                else
                {
                    packet.put_byte(1);
                }
            }
            packet.finalize(true);
            party->send_to_party(packet);
            party->SetTournamentDungeonClearState((char)0x02);
            party->InsertTournamentDungeonTimer((TIMER_MESSAGE)0x2f);
        }
    }
}


