    // 出 `mov %eax,-off(%ebp)` RHS-first）；world 无槽链式；proxy 链式右值（ebx=&pkt）。
    if (user->get_state() <= 2 || user->getCurCharacR() == 0
        || !user->isGMUser())
    {
        return 0;
    }
    Pakcet_FindUserName_use_Charac_no request;
    request.m_uid = user->GetUID();              // +0x0a（ORIG -0x42）
