// ==== Dispatcher_PcRoomRentItem::check_error (ORIG 0x081e5762) ====
// b28d-solo-Dispatchers verdict=AE(routed) [S206 翻正] ORIG 0x081e5762
//   [N7→P224/P45] 根因=合取形 `A&&B{body}` 产 je 反向首跳；改否定短路
//   `state!=3 || characR==0 → return 3`（ORIG cmp/jne + mov$1/$0 汇聚岛）⇒ 归零。
int Dispatcher_PcRoomRentItem::check_error(CUser* user, MSG_BASE& msg)
{
    // 【实测记录 batch-17】改写为 `invalid = (state != 3) || (characR == 0)`
    // 命名 bool + `if (invalid) return 3;` 可让首跳方向与 ORIG 一致（jne），但
    // 4.4 会把 bool 落槽再 `mov; cmpb` 回读（70/71）；保持合取原形为 70/70，
    // 故此处保留 && 形，方向差记 N76/N18a（勿再改写）。
    // [b28d-solo-S206] P224/P45 极性翻正：ORIG 0x081e5762 `cmp $3,%eax; jne <mov$1岛>`
    //   + `call; test; jne <mov$0岛>` + 汇聚 `test %al; je 主体; mov $3` ⇒ 原码是
    //   否定短路 `state!=3 || characR==0`（非 `A&&B{body}` 形，后者产 je 反向首跳）。
    if (user->get_state() != 3 || user->getCurCharacR() == 0)
    {
        return 3;
    }
    {
        // ①ORIG 0x081e577x：msg 引用槽在 state/characR 判定**之后**才物化
        //   （`mov 0x10(%ebp),%eax; mov %eax,-0xc(%ebp)`，技巧13 声明位=落栈时机）；
        //   我方在函数入口物化，槽号亦从 -0xc 漂到 -0x10。
        MSG_RENT_ITEM& req = reinterpret_cast<MSG_RENT_ITEM&>(msg);
        // ②ORIG 对该 byte 字段是**两次独立装载 + 寄存器测**（`movzbl 0xe(%eax),%eax;
        //   testb %al,%al; jle` 与再装载一次 `cmp $2,%al; jle`），我方具名 char 局部
        //   使 4.4 折成 `mov %al,-0x9(%ebp)` + 两次 `cmpb $K,-0x9(%ebp)`（技巧36）。
        //   整数域内 `type <= 0` 与原 `type < 1` 等价，语义不变。
        if (static_cast<signed char>(req.m_0e) <= 0 ||
            static_cast<signed char>(req.m_0e) > 2)
        {
            return 8;
        }
        if (user->GetPCRoomNo() == 0 && static_cast<signed char>(req.m_0e) == 1)
        {
            return 8;
        }
        // type==2：重复租借事件(0x5e)未进行中 → 错误。vptr+0x34 槽 = IsEventing。
        // 【batch-17 DispC8 交接项】必须写**嵌套独立 if**：ORIG 0x081e57f5..0x081e5835
        // 是 `cmp $0x2,%al; jne 尾` + `call IsEventing; xor $0x1,%eax; test%al;
        // je 尾` + `mov $0x8,%eax; jmp end`，即两个条件各自 jcc 直跳、**无 bool
        // 汇聚**；写成 `A && !call()` 会让 4.4 生成 `mov$1/jmp/mov$0` 汇聚岛
        // （实测多 7 insn，70/75 → 70/70 的达成点）。
        if (static_cast<signed char>(req.m_0e) == 2)
        {
            if (!GlobalData::s_event_manager->GetRepeatEvent(0x5e)
                     ->IsEventing((CUser*)0))
            {
                return 8;
            }
        }
        return 0;
    }
}

// ==== Dispatcher_PcRoomRentItem::read (ORIG 0x081e512e) ====
// b28d-solo-Dispatchers verdict=DIFF(routed) [N-P112] ORIG 0x081e512e orig/ours=96/94 ndiff-blocks=13
//   残余为跨版本寄存器分配/栈槽序差（P75/P112 结构性），语义已对齐
//   首差: mov    %eax,-0x10(%ebp) | mov    -0x10(%ebp),%eax | movl   $&_ZZN25Dispatcher_PcRoomRentItem4readER9PacketBufR8MSG_BASEE19__PRETTY_FUNCTION__,0x4(%esp
int Dispatcher_PcRoomRentItem::read(PacketBuf& packet, MSG_BASE& msg)
{
    MSG_RENT_ITEM& req = reinterpret_cast<MSG_RENT_ITEM&>(msg);
    if (!packet.get_byte(reinterpret_cast<char&>(req.m_0e)))          // +0x0e type
    {
        return LineFunc(24124,
                        __PRETTY_FUNCTION__,
                        0, 0);
    }
    if (!packet.get_byte(reinterpret_cast<char&>(req.m_0d)))          // +0x0d count
    {
        return LineFunc(24128,
                        __PRETTY_FUNCTION__,
                        0, 0);
    }
    // ORIG 0x081e51xx：两判定各自 `mov -0x10(%ebp),%eax; movzbl 0xd(%eax),%eax`
    // —— count 值**无栈槽往返**（P0：具名 char 局部会占 -0xd 并把 msg 槽顶到 -0x14）。
    if (static_cast<char>(req.m_0d) < 1 ||
        static_cast<char>(req.m_0d) > 1)                              // 恒为 1 项
    {
        return LineFunc(24131,
                        __PRETTY_FUNCTION__,
                        0, 0);
    }
    for (int i = 0; i < static_cast<int>(static_cast<char>(req.m_0d)); ++i)
    {
        // 元素对 @+0x0f+2i/+0x10+2i（RentInElem sectionIdx/itemIdx；count==1 不越界）
        if (!packet.get_byte(req.m_0f[i * 2]))
        {
            return LineFunc(24136,
                            __PRETTY_FUNCTION__,
                            0, 0);
        }
        if (!packet.get_byte(req.m_0f[i * 2 + 1]))
        {
            return LineFunc(24138,
                            __PRETTY_FUNCTION__,
                            0, 0);
        }
    }
    return 0;
}

// ==== Dispatcher_PcRoomRentItem::process (ORIG 0x081e52c0) ====
// b28d-solo-Dispatchers verdict=DIFF(routed) [N-P112] ORIG 0x081e52c0 orig/ours=113/115 ndiff-blocks=8
//   残余为跨版本寄存器分配/栈槽序差（P75/P112 结构性），语义已对齐
//   首差: mov    %eax,%edx | mov    -0x14(%ebp),%eax | mov    %edx,0x4(%eax)
int Dispatcher_PcRoomRentItem::process(CUser* user, MSG_BASE& msg, ParamBase& param)
{
    stRentItemParam& out = static_cast<stRentItemParam&>(param);
    MSG_RENT_ITEM& req = reinterpret_cast<MSG_RENT_ITEM&>(msg);

    out.m_4 = check_error(user, msg);
    if (out.m_4 != 0)
    {
        return 0;
    }

    InstanceRentalSystem::RentInput input;               // ctor 清 vector/machineKey
    input.m_logFlag = 1;                                 // +0x10 log 开关（PcRoom 报告实证）
    input.m_machineKey = static_cast<int>(static_cast<char>(req.m_0e));
    // ORIG 0x081e52c0：两读取为 `movzbl 0xf(%eax,%edx,2)` / `movzbl 0x10(%eax,%edx,2)`
    // —— 基址=msg(-0x10)、**缩放因子 2**、disp 0xf 与 0x10 ⇒ 原码是 msg+0xf 起的
    // 2 字节元素结构数组（uchar 对），非 `char[]` 的 `i*2`/`i*2+1` 下标形
    // （后者 4.4 恒产 lea+×1，P311 成员数组视图判据）。MSG 头冻结 ⇒ 本 TU 视图承接。
    struct __attribute__((packed)) RentPairView
    {
        char m_head[0xf];
        struct Pair { unsigned char m_sectionIdx, m_itemIdx; } m_pairs[1];  // +0xf 起
    };
    // 视图指针**不落槽**（ORIG 无该槽，P0）⇒ 每使用点内联 cast 表达式。
    for (int i = 0; i < static_cast<int>(static_cast<char>(req.m_0d)); ++i)
    {
        InstanceRentalSystem::RentInElem elem;
        elem.m_sectionIdx =
            reinterpret_cast<RentPairView*>(&msg)->m_pairs[i].m_sectionIdx;
        elem.m_itemIdx =
            reinterpret_cast<RentPairView*>(&msg)->m_pairs[i].m_itemIdx;
        input.m_elems.push_back(elem);
    }

    giveDimensionItems(user, input);

    out.m_4 = static_cast<int>(
        static_cast<InstanceRentalSystem*>(GlobalData::s_rentalSystem)
            ->Rent(*user, input, out.m_output));
    if (out.m_4 == 0)
    {
        user->UpdateCurrentCharacRentalInfo(
            out.m_output, (int)(char)req.m_0e, false);
    }
    return 0;                                            // ORIG RentInput dtor 于帧尾
}

// ==== Dispatcher_PcRoomRentItem::giveDimensionItems (ORIG 0x081e583e) ====
// 注：ORIG 为类成员（见文件头宿主声明补充说明）。
// b28d-solo-Dispatchers verdict=DIFF(routed) [N82] ORIG 0x081e583e orig/ours=78/74 ndiff-blocks=14
//   帧差 sub $3c vs $38 + 槽号漂移（4.1 不按 lifetime 复用栈槽）
//   首差: push   %edi | push   %esi | push   %ebx
void Dispatcher_PcRoomRentItem::giveDimensionItems(CUser* user,
                                                   InstanceRentalSystem::RentInput& input)
{
    if (user == 0 || input.m_machineKey != 2)            // 仅 dimension(machineKey==2)
    {
        return;
    }
    int selectionIdx = 0;
    if (!pc_room::GetSelectionIndex(*user, selectionIdx, 2))
    {
        return;
    }
    int growType = static_cast<int>(user->getCurCharFirstGrowType());   // W 0x08110c94
    int job = user->get_charac_job();                                    // W 0x080fdf20

    // ORIG 0x081e58c3: rewardData->getRewardGiveItems(selectionIdx, job, growType)，
    // 非空则逐项组装 RentInElem 入 input.m_elems（m_type=1 GiveList 标记）
    DimensionActivationRewardData* rewardData =
        reinterpret_cast<DimensionActivationRewardData*>(
            reinterpret_cast<char*>(G_CDataManager()) + 0x4b34);
    std::vector<EventRewardItemInfo>* items =
        rewardData->getRewardGiveItems(selectionIdx, job, growType);
    if (items != 0)
    {
        for (int i = 0; i < static_cast<int>(items->size()); ++i)
        {
            InstanceRentalSystem::RentInput::RentInElem elem;
            elem.m_sectionIdx = static_cast<unsigned char>(selectionIdx);
            elem.m_itemIdx = static_cast<unsigned char>(i);
            elem.m_type = 1;                             // GiveList 路径标记
            input.m_elems.push_back(elem);
        }
    }
}

// ==== Dispatcher_PcRoomRentItem::send (ORIG 0x081e542e) ====
// b28d-solo-Dispatchers verdict=DIFF(routed) [N-P112] ORIG 0x081e542e orig/ours=229/221 ndiff-blocks=51
//   残余为跨版本寄存器分配/栈槽序差（P75/P112 结构性），语义已对齐
//   首差: mov    %eax,-0x1c(%ebp) | mov    -0x1c(%ebp),%eax | add    $0x8,%eax
void Dispatcher_PcRoomRentItem::send(CUser* user, ParamBase& param)
{
    stRentItemParam& out = static_cast<stRentItemParam&>(param);
    bool sendEquipSlot10 = false;

    PacketGuard packet;
    packet.put_header(1, 0x1ee);                         // class=1 cmd=0x1ee
    if (out.m_4 == 0)
    {
        packet.put_byte(1);
        packet.put_byte(static_cast<int>(out.m_output.m_deleted.size()));
        for (std::vector<InstanceRentalSystem::DeletedRentItem>::iterator it =
                 out.m_output.m_deleted.begin();
             it != out.m_output.m_deleted.end(); ++it)
        {
            // [b28d-solo-Dispatchers] P167/P183：ORIG 0x081e54d3 只调 1 次
            //   `normal_iterator<DeletedRentItem>::deEv`（operator*），结果落 -0x10
            //   槽后各字段点重读（0x081e54f8/0x081e5505/0x081e552b 均
            //   `mov -0x10(%ebp),%eax; movzwl 0x2(%eax)`）；旧码 `it->` 调 ptEv ×2
            //   且 slot 具名局部缓存。⇒ 改 `r = *it` 引用 + 各点 r.m_slot 重读。
            InstanceRentalSystem::DeletedRentItem& r = *it;
            if (r.m_bEquip == 0)                                      // +0x00
            {
                packet.put_byte(0);
            }
            else
            {
                packet.put_byte(3);
                if (r.m_slot > 9 && r.m_slot < 0x16)
                {
                    sendEquipSlot10 = true;                           // 装备位 9..0x15 变动
                }
            }
            packet.put_short(static_cast<int>(r.m_slot));
        }
    }
    else
    {
        packet.put_byte(0);
        packet.put_byte(out.m_4 & 0xff);
    }
    packet.finalize(true);
    user->Send(packet);

    if (out.m_4 == 0)
    {
        PacketGuard infoPacket;
        infoPacket.put_header(0, 0xe);                   // class=0 cmd=0xe 租借列表刷新
        infoPacket.put_byte(0);
        infoPacket.put_short(static_cast<int>(out.m_output.m_infos.size()));
        // [b28d-solo-Dispatchers] P167：ORIG 0x081e5662 调 const_iterator 的 deEv
        //   （`IPKN…`）+ 0x081e56c7 混合 ne + 0x081e563x 转换构造 ⇒ 原码是
        //   const_iterator + `(*it).m_slot`（旧码 iterator + `it->` 调 ptEv）。
        for (std::vector<InstanceRentalSystem::RentalInfo>::const_iterator it =
                 out.m_output.m_infos.begin();
             it != out.m_output.m_infos.end(); ++it)
        {
            const CInventory* inven = const_cast<CInventory*>(user->getCurCharacInvenR());
            inven->MakeItemPacket(INVEN_TYPE_EQUIP,
                                  static_cast<int>(static_cast<short>((*it).m_slot)),
                                  infoPacket);
        }
        infoPacket.finalize(true);
        user->Send(infoPacket);
    }

    if (sendEquipSlot10)
    {
        user->send_equip(10);
    }
}

