// ==== Dispatcher_RequestIngameAdvertisement::check_error (ORIG 0x081e4662) ====
// b28d-solo-Dispatchers verdict=AE(routed) [S206 翻正] ORIG 0x081e4662
//   [N96→P316/P226] 根因=具名 bool ok 落槽（-0x9 存取对）且 p 槽 -0xc→-0x10；
//   改语句表达式 `if (({ failCnt<=2; }))` 零槽寄存器物化（setle;test;je）⇒ 归零。
int Dispatcher_RequestIngameAdvertisement::check_error(CUser* user, MSG_BASE& msg)
{
    if (user == 0)
    {
        return -1;                                          // 0xffffffff
    }

    if (user->get_state() <= 1)                             // cmp $1,setle（P2 有符号比较）
    {
        return 0x7fffffff;
    }

    // ORIG 0x081e4691：msg 指针先物化 -0xc 槽再单级 disp 读（具名指针局部，
    // 技巧13 落栈时机=声明位置）；`cmp $0x6,%ax` 16 位寄存器比较；failCnt
    // <=2 走 bool 物化 `cmp $2; setle %al; test`（技巧9/19，勿写 <3 被折 jg）。
    MSG_REQUEST_INGAME_ADVERTISEMENT* p =
        reinterpret_cast<MSG_REQUEST_INGAME_ADVERTISEMENT*>(&msg);
    if (p->m_field0d == 6)
    {
        // ORIG 0x081e46aa：`call; cmp $2,%eax; setle %al; test %al,%al; je`
        //   （寄存器物化、零槽）。直写 `(bool)` 被 4.4 折 jg+mov$1/$0 岛；
        //   具名 bool 落槽（-0x9 存取对）并使 p 槽 -0xc→-0x10。
        // [b28d-solo-S206] P316/P226 语句表达式形（内不含具名变量）零槽复现。
        if (({ user->get_multiboxLotteryItemFailCnt() <= 2; }))
        {
            return -2;                                  // 0xfffffffe
        }
    }

    return 0;
}

// ==== Dispatcher_RequestIngameAdvertisement::read (ORIG 0x081e434c) ====
int Dispatcher_RequestIngameAdvertisement::read(PacketBuf& packet, MSG_BASE& msg)
{
    // ORIG（帧 $0x28）：msg 指针先物化 -0xc 再回读算址 ⇒ 命名局部。
    char* p = reinterpret_cast<char*>(&msg);
    if (!packet.get_short(*reinterpret_cast<short*>(p + 0xd)))
    {
        return LineFunc(
            0x5c10,
            __PRETTY_FUNCTION__,
            0, 0);
    }
    return 0;
}

// ==== Dispatcher_RequestIngameAdvertisement::process (ORIG 0x081e43a2) ====
// ParamBase 绝对偏移（汇编 disp 原样）：
//   +0x640 int 错误码 | +0x644 short 广告类型（回显 msg+0xd）
//   +0x004 起内嵌 stNotifyIngameADInfo（未建模，全偏移承载）：
//     +0x004 int（send put_int 首字段/WriteLog 第 5 参 uint）
//     +0x008 char[]（描述文本，strlen 口径）| +0x03a char[]（备选文本）
//     +0x139 char[] / +0x238 int / +0x23c char[] / +0x33b byte 广告形态 /
//     +0x33c byte 日志开关 / +0x33d byte 奖品形态 / +0x33e char[] /
//     +0x43d char[] / +0x53c ulong 奖品 idx A / +0x540 char[] / +0x23c 同理 B 区
// b28d-solo-Dispatchers verdict=DIFF(routed) [N-P197④] ORIG 0x081e43a2 orig/ours=182/186 ndiff-blocks=12
//   ORIG setcc 物化（bool 归一岛）而 4.4 折直跳/槽化，源形不可择
//   首差: movl   $&_ZZN37Dispatcher_RequestIngameAdvertisement7processEP5CUserR8MSG_BASER9ParamBaseE19__PRETTY_FUNCTION__,0x4(%esp) | mov    0x10(%ebp),%eax | m
int Dispatcher_RequestIngameAdvertisement::process(CUser* user, MSG_BASE& msg,
                                                   ParamBase& param)
{
    stRequestIngameAdvertisement* R =
        reinterpret_cast<stRequestIngameAdvertisement*>(&param);
    MSG_REQUEST_INGAME_ADVERTISEMENT& M =
        reinterpret_cast<MSG_REQUEST_INGAME_ADVERTISEMENT&>(msg);

    R->m_errorCode = check_error(user, msg);

    if (R->m_errorCode >= 1)
    {
        return 0;
    }
    if (R->m_errorCode < 0)
    {
        LineFunc(
            0x5c20,
            __PRETTY_FUNCTION__,
            R->m_errorCode, 0);
        return 0;
    }

    // err == 0 主流程
    R->m_adType = M.m_field0d;

    if (InGameADManagerInstance()->CheckIngameAdvertisementCondition(
            user, *reinterpret_cast<stNotifyIngameADInfo*>(&R->m_code),
            (int)M.m_field0d))
    {
        if (R->m_adShape == 4 && user->get_multiboxLotteryItemFailCnt() > 2)
        {
            if (R->m_prizeShape != 0 && R->m_itemID != 0)
            {
                sendRewardItemSystemMail(user, R->m_itemID, 1);
                if (R->m_logFlag != 0)
                {
                    InGameADManagerInstance()->WriteLog(
                        user, '\x03', M.m_field0d,
                        (char)R->m_adShape, R->m_code);
                }
            }
            else if (R->m_prizeShape == 0 && R->m_itemID2 != 0)
            {
                sendRewardItemSystemMail(user, R->m_itemID2, 1);
                if (R->m_logFlag != 0)
                {
                    InGameADManagerInstance()->WriteLog(
                        user, '\x03', M.m_field0d,
                        (char)R->m_adShape, R->m_code);
                }
            }

            user->set_multiboxLotteryItemFailCnt(0);        // 0x080fdf44
        }

        if (R->m_logFlag != 0)
        {
            InGameADManagerInstance()->WriteLog(
                user, '\0', M.m_field0d,
                (char)R->m_adShape, R->m_code);
        }
    }
    else
    {
        *reinterpret_cast<int*>(reinterpret_cast<char*>(R) + 0x640) = 4;             // 条件不满足固定错误码
    }

    return 0;
}

// ==== Dispatcher_RequestIngameAdvertisement::send (ORIG 0x081e46c8) ====
// b28d-solo-Dispatchers verdict=DIFF(routed) [N82] ORIG 0x081e46c8 orig/ours=319/292 ndiff-blocks=26
//   帧差 sub $40 vs $50 + 槽号漂移（4.1 不按 lifetime 复用栈槽）
//   首差: sub    $0x40,%esp | mov    %eax,-0x14(%ebp) | mov    -0x14(%ebp),%eax
void Dispatcher_RequestIngameAdvertisement::send(CUser* user, ParamBase& param)
{
    // 具名访问：stRequestIngameAdvertisement（PacketTypes.h 权威布局，总长 0x648）。
    // 字符串区落冻结头 pad 区（已 hub 报 Main 补具名串字段），此处以具名成员为基址。
    stRequestIngameAdvertisement& R =
        reinterpret_cast<stRequestIngameAdvertisement&>(param);
    const int err = R.m_errorCode;                                  // +0x640

    if (err == 0x7fffffff)
    {
        return;                                             // check_error 未跑（state 门早退）
    }

    if (err != 0)
    {
        // [b28d-solo-Dispatchers] ORIG 两个独立 PacketGuard：错误路径 -0x20
        //   （C1Ev 0x081e4701 / D1Ev 0x081e4a7d+0x081e4a94 EH），成功路径 -0x2c
        //   （C1Ev 0x081e4aa4）。p167 旧态 MISSING C2×2/D2×4/_Unwind_Resume×1、
        //   EXTRA C1×1/D1×2 ⇒ 原码是**两个分支各自作用域的 guard**，非函数级复用。
        // ---- 错误回包：byte 0 + err + type ----
        PacketGuard pg;
        pg.clear();                                         // InterfacePacketBuf::clear
        pg.put_header(1, 0x1e9);
        pg.put_byte(0);
        pg.put_byte(err & 0xff);
        pg.put_short(R.m_adType);                                   // +0x644
        pg.finalize(true);
        user->Send(pg);
        return;
    }

    // ---- 成功回包 ----
    PacketGuard pg;                                         // ORIG -0x2c
    pg.clear();
    pg.put_header(1, 0x1e9);
    pg.put_byte(1);
    pg.put_int(static_cast<int>(R.m_code));                         // +0x004
    pg.put_short(R.m_adType);                                       // +0x644
    // 以下 m_adShape/m_logFlag/m_prizeShape 与文本区字段同属 +0x04 内嵌通知信息块
    pg.put_byte(static_cast<signed char>(R.m_adShape));             // +0x33b

    {
        const int descLen =
            static_cast<int>(strlen(R.m_pad08));                    // +0x008
        pg.put_int(descLen);
        pg.put_str(R.m_pad08, descLen);
    }

    pg.put_byte(static_cast<signed char>(R.m_prizeShape));          // +0x33d

    if (R.m_prizeShape == 0)
    {
        const int textLen =
            static_cast<int>(strlen(R.m_pad33e));                   // +0x33e
        pg.put_int(textLen);
        pg.put_str(R.m_pad33e, textLen);

        const unsigned char kind =
            R.m_adShape;                                            // +0x33b
        if (kind == 0)
        {
            pg.put_int(static_cast<int>(R.m_itemID2));              // +0x53c
        }
        else if (kind == 1)
        {
            const int len =
                static_cast<int>(strlen(R.m_pad33e + 0xff));        // +0x43d
            pg.put_int(len);
            pg.put_str(R.m_pad33e + 0xff, len);
        }
        else if (kind == 3)
        {
            const int len =
                static_cast<int>(strlen(R.m_pad540));               // +0x540
            pg.put_int(len);
            pg.put_str(R.m_pad540, len);
        }
    }
    else
    {
        const int textLen =
            static_cast<int>(strlen(R.m_pad08 + 0x32));             // +0x03a
        pg.put_int(textLen);
        pg.put_str(R.m_pad08 + 0x32, textLen);

        const unsigned char kind =
            R.m_adShape;                                            // +0x33b
        if (kind == 0)
        {
            pg.put_int(static_cast<int>(R.m_itemID));               // +0x238
        }
        else if (kind == 1)
        {
            const int len =
                static_cast<int>(strlen(R.m_pad08 + 0x131));        // +0x139
            pg.put_int(len);
            pg.put_str(R.m_pad08 + 0x131, len);
        }
        else if (kind == 3)
        {
            const int len =
                static_cast<int>(strlen(R.m_pad23c));               // +0x23c
            pg.put_int(len);
            pg.put_str(R.m_pad23c, len);
        }
    }

    pg.put_byte(static_cast<signed char>(R.m_logFlag));             // +0x33c
    pg.finalize(true);
    user->Send(pg);
}

// ==== Dispatcher_RequestIngameAdvertisement::sendRewardItemSystemMail (ORIG 0x081e4b6c) ====
// 头声明缺失：宿主需在 Dispatchers.h 补
//   void sendRewardItemSystemMail(CUser* user, unsigned long itemIdx, int count);
void Dispatcher_RequestIngameAdvertisement::sendRewardItemSystemMail(
    CUser* user, unsigned long itemIdx, int count)
{
    // [b28c-34] ORIG 0x081e4cc4/0x081e4cc5 两处 je 目标相邻（共享尾岛 +0x159）；
    // ORIG 岛数 = 1（body 尾 `jmp +0x159; nop`，两 je 直达）⇒ 单早返 + 正向包裹。
    if (user == 0)
        return;
    CItem* find = G_CDataManager()->find_item(static_cast<int>(itemIdx));   // -0xc（CItem* 指针槽）
    if (find != 0)
    {
        Inven_Item item;                                        // ORIG C1 W 0x080cb854
        item.m_addInfo = static_cast<int>(itemIdx);             // +0x02（item idx）
        G_CDataManager()->m_itemList->create_item(ENUM_ITEM_CREATE_TYPE_0, item, count);

        // RDAR 字符串：发件人名（≤0x1d）/ 正文（≤0xff），strncpy 不手动补 NUL（同 ORIG）
        char sender[0x1e];                                      // ORIG local [30] @ -0x2a
        strncpy(sender,
                g_scriptStringManager_.findString(4, "game_server_msg_295", 0),
                0x1d);
        char body[0x100];
        strncpy(body,
                g_scriptStringManager_.findString(4, "game_server_msg_296", 0),
                0xff);

        WongWork::CMailBoxHelper::ReqDBSendNewSystemMail(
            sender, item, 0u,
            static_cast<unsigned int>(user->getCurCharacNo()),
            body, static_cast<int>(strlen(body)), 0u,
            user->GetServerGroup(), false, false);
    }
}

