// b28d-solo-Dispatchers verdict=DIFF(routed) [N-P112] ORIG 0x081d14aa orig/ours=81/80 ndiff-blocks=13
//   残余为跨版本寄存器分配/栈槽序差（P75/P112 结构性），语义已对齐
//   首差: jne    081d14d7 <+0x2d> | mov    $0xffffffff,%eax | jmp    081d15ab <+0x101>
int Dispatcher_GuildCargoPopItem::check_error(CUser* user, MSG_BASE& msg,
                                               ParamBase& param)
{
    if (user->get_state() == 3 && user->getCurCharacR() != 0)
    {
        int guildkey = user->get_charac_guildkey();     // ORIG 0x080da38c 后链
        if (guildkey != 0)
        {
            // X1 位 A：ORIG 0x082301d8 此处是 `test;sete %al;test %al,%al;je` 物化岛
            // （台账 ours_only 缺 sete/test），bool callee 用 (x == 0) 才出 sete；
            // 裸 !boolcall() 反而出 xor 单段（技巧9/19 与技巧1 的分界）。
            if ((bool)(user->IsExistGuildAgit() == 0))
            {
                return 0xb5;
            }
            {
                int secu = GlobalData::s_pSecuProtectionField->Check(
                    user, (SECURITY_PROTCTION)9);       // ORIG 0x08288a02
                if (secu != 0)
                    return secu;
                // 位 C：ORIG 0x081d16ex 是 `mov 0x10(%ebp),%eax; mov 0xf(%eax),%ebx`
                // —— packed 具名视图给单级 disp（技巧14/F），register 绑 %ebx 同时把
                // 值钉进 callee-saved（消掉我方裸偏移写法的 add+mov 三步，并让
                // prologue 回到 ORIG 的 `push %ebx; sub $0x24,%esp`）。
                struct __attribute__((packed)) CargoPopParamView {
                    char m_head[0xf];
                    int m_itemIdx;                   // +0x0f
                };
                int itemIdx =
                    reinterpret_cast<CargoPopParamView*>(&param)->m_itemIdx;
                const CInventory* inven = user->getCurCharacInvenR();
                // X1 位 B：ORIG 0x0850562a 之后是 `test %eax,%eax; jne` 直分支
                // （int callee 免物化），我方 `!intcall()` 恒被折成 sete 岛 ⇒ 写 == 0。
                if (inven->possible_to_insert(itemIdx) == 0)
                    return 0xcb;
                if (G_CDataManager()->find_item(itemIdx) == 0)   // ORIG 0x0835fa32
                    return 0xc5;
                return 0;
            }
        }
        return 100;
    }
    return -1;
}

int Dispatcher_GuildCargoMoveItem::check_error(CUser* user, MSG_BASE& msg,
                                               ParamBase& param)
{
    // ORIG 0x081d18dc 控制流（技巧6/7 线性 early-return + 技巧40 flag-island）：
    // state==3 && characR!=0 物化成 %eax 双岛后 `test %al,%al; je 岛(-1)`；
    // guildkey `test;sete %al`（==0 → 100）；agit `xor $1;test;je`（false → 0xb5）；
    // 全部通过则 fall 到 `mov $0x0` 尾岛。
    if (!(user->get_state() == 3 && user->getCurCharacR() != 0))
        return -1;
    if (user->get_charac_guildkey() == 0)
        return 100;
    if (!user->IsExistGuildAgit())
        return 0xb5;
    return 0;
}

// b28d-solo-Dispatchers verdict=DIFF(routed) [N-P112] ORIG 0x081d1ebe orig/ours=54/45 ndiff-blocks=3
//   残余为跨版本寄存器分配/栈槽序差（P75/P112 结构性），语义已对齐
//   首差: lea    0x4d44(%eax),%edx | lea    -0x10(%ebp),%eax | lea    -0x10(%ebp),%eax
int Dispatcher_ChangeEmotion::isVaildEmotionValue(short value)
{
    // 【batch-17 实测记录，勿再改写】三形对比（ORIG 54）：
    //   A 缓存 vector 引用 + for(it=begin(); it!=end(); ++it)      → 45（gap +9，最优）
    //   B 两迭代器先默认构造 + begin/end 各重发 G_CDataManager     → 64（gap -10）
    //   C 声明即初始化 + 双臂重发 G_CDataManager                   → 居中但差集仍缺
    // ⇒ 该函数残 9 insn 属 4.1 out-of-line STL 实例发射差（N89 族，
    //   docs/function_audit/N89_EXCLUSION*.tsv 判据），非源码可闭合；保留 A 形。
    // [b28d-solo-Dispatchers] P96：ORIG 0x081d1ebe 用**非 const** 容器 begin/end
    //   （p167 MISSING `_ZNSt6vectorIiSaIiEE5beginEv/3endEv` + `const_iterator(int*)`
    //   转换构造 C2IPiE），const 引用会走 K 版 ⇒ 改非 const 引用、迭代器仍 const_iterator。
    // [b28d-solo-Dispatchers] P183：ORIG 0x081d1ebe 两处各自完整调 G_CDataManager()
    //   （p167 MISSING `_Z14G_CDataManagerv` ×1 = tags 引用缓存省掉的那次）；
    //   P326：显式 const_iterator 转换临时复现 ORIG 的 C2IPiE 转换 ×2 + 同型 ne。
    for (std::vector<int>::const_iterator it =
             G_CDataManager()->m_emotionTags.m_tags.begin();
         it != std::vector<int>::const_iterator(
                   G_CDataManager()->m_emotionTags.m_tags.end()); ++it)
    {
        if (*it == (int)value)
            return 1;
    }
    return 0;
}

